type Store = "Viterbo" | "Gran Sasso";
type User = { id: number; username: string; displayName: string; role: "admin" | "viterbo" | "gran_sasso"; store: Store | null; mustChangePassword: number };
type Product = { id: number; sku: string; name: string; brand: string; category: string; color: string; size: string; price: number; variantGroup: string | null; photoKey: string | null; eans: string; viterboQty: number; viterboReserved: number; granSassoQty: number; granSassoReserved: number };
type ProductGroup = { key: string; name: string; brand: string; category: string; variants: Product[] };
type Customer = { id: number; customerType: "private" | "company"; firstName: string; lastName: string; companyName: string; vatNumber: string; pec: string; sdiCode: string; phone: string; email: string; address: string; postalCode: string; city: string; province: string; taxCode: string; scope: string; createdStore: Store; createdAt: string };
type Sale = { id: number; receiptNo: string; store: Store; customerId: number | null; customerName: string; type: string; subtotal: number; adjustment: number; total: number; cashAmount: number; cardAmount: number; bankAmount: number; giftAmount: number; fiscalStatus: string; fiscalDocumentType: string; createdAt: string };
type Gift = { id: number; code: string; beneficiary: string; initialValue: number; balance: number; expiresAt: string; store: Store; issuedSaleId: number; status: string; createdAt: string };
type Reservation = { id: number; code: string; store: Store; customerId: number | null; productId: number | null; description: string; kind: string; totalPrice: number; depositAmount: number; balanceDue: number; status: string; issuedSaleId: number; createdAt: string; customerName: string; itemCount: number; itemDescriptions: string };
type Transfer = { id: number; code: string; fromStore: Store; toStore: Store; sender: string; receiver: string; carrier: string; transportReason: string; createdAt: string; lineCount: number; totalQuantity: number };
type BusinessDocument = { id: number; number: string; type: string; recipient: string; origin: string; paymentMethod: string; saleId: number | null; netTotal: number; taxTotal: number; total: number; createdAt: string };
type SaleItemSummary = { id: number; saleId: number; productId: number | null; description: string; quantity: number; lineTotal: number; itemType: string; store: Store; createdAt: string; brand: string; productName: string; color: string; size: string; variantGroup: string };
type FiscalDevice = { id: number; store: Store; vendor: string; model: string; connector: string; enabled: number; hasToken: number; lastSeenAt: string | null; lastStatus: string; lastError: string | null; updatedAt: string };
type FiscalJob = { id: number; saleId: number; store: Store; jobType: string; status: string; attempts: number; deviceResponse: string | null; createdAt: string; claimedAt: string | null; completedAt: string | null; receiptNo: string };
type Bootstrap = { user: User; products: Product[]; customers: Customer[]; sales: Sale[]; gifts: Gift[]; reservations: Reservation[]; transfers: Transfer[]; documents: BusinessDocument[]; saleItems?: SaleItemSummary[]; fiscalDevices: FiscalDevice[]; fiscalJobs: FiscalJob[]; generatedAt: string };
type CartItem = { key: string; productId: number | null; description: string; quantity: number; unitPrice: number; itemType: string; locked?: boolean; metadata: Record<string, unknown> };

const money = (value: number) => new Intl.NumberFormat("it-IT", { style: "currency", currency: "EUR" }).format(Number(value) || 0);
const dateTime = (value: string) => new Date(value).toLocaleString("it-IT", { dateStyle: "short", timeStyle: "short" });
const todayPlusYear = () => new Date(Date.now() + 365 * 86400000).toISOString().slice(0, 10);
const keyId = () => `${Date.now()}-${Math.random().toString(16).slice(2)}`;
const variantCollator = new Intl.Collator("it", { numeric: true, sensitivity: "base" });
const customerLabel = (customer: Customer) => customer.customerType === "company" ? customer.companyName : `${customer.firstName} ${customer.lastName}`.trim();

function groupProducts(products: Product[]): ProductGroup[] {
  const groups = new Map<string, ProductGroup>();
  for (const product of products) {
    const fallback = `${product.brand}|${product.name}|${product.category}`.trim().toLocaleLowerCase("it");
    const key = product.variantGroup?.trim() || fallback;
    const group = groups.get(key) ?? { key, name: product.name, brand: product.brand, category: product.category, variants: [] };
    group.variants.push(product);
    groups.set(key, group);
  }
  return [...groups.values()].map((group) => ({
    ...group,
    variants: group.variants.sort((left, right) => variantCollator.compare(left.color, right.color) || variantCollator.compare(left.size, right.size)),
  })).sort((left, right) => `${left.brand} ${left.name}`.localeCompare(`${right.brand} ${right.name}`, "it"));
}

function searchableProduct(product: Product) {
  return `${product.brand} ${product.name} ${product.category} ${product.sku} ${product.color} ${product.size} ${product.eans}`.toLocaleLowerCase("it");
}

function makeEan13() {
  const base = `29${Date.now().toString().slice(-10)}`.slice(0, 12);
  let sum = 0;
  for (let index = 0; index < 12; index += 1) sum += Number(base[index]) * (index % 2 === 0 ? 1 : 3);
  return `${base}${(10 - (sum % 10)) % 10}`;
}

async function readJson(response: Response) {
  const data = await response.json().catch(() => ({ error: "Risposta non valida." }));
  if (!response.ok) throw Object.assign(new Error(data.error ?? "Operazione non riuscita."), { data, status: response.status });
  return data;
}

async function post(action: string, values: Record<string, unknown> = {}) {
  return readJson(await firebaseAuthenticatedFetch("/api/data", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ action, ...values }) }));
}

type ClearableInputProps = Omit<InputHTMLAttributes<HTMLInputElement>, "onChange"> & { label?: string; value: string | number; onChange: (value: string) => void; compact?: boolean };
function ClearableInput({ label, value, onChange, compact, className = "", ...props }: ClearableInputProps) {
  return <label className={`field ${compact ? "field-compact" : ""} ${className}`}>{label && <span>{label}</span>}<span className="input-wrap"><input {...props} value={value} onChange={(event) => onChange(event.target.value)} />{String(value).length > 0 && <button type="button" className="clear-input" aria-label={`Cancella ${label ?? "campo"}`} onClick={() => onChange("")}>×</button>}</span></label>;
}

function Modal({ title, children, onClose }: { title: string; children: ReactNode; onClose: () => void }) {
  return <div className="modal-backdrop" role="dialog" aria-modal="true"><div className="modal"><div className="modal-head"><h2>{title}</h2><button className="icon-button" onClick={onClose} aria-label="Chiudi">×</button></div>{children}</div></div>;
}

function Empty({ children }: { children: ReactNode }) { return <div className="empty">{children}</div>; }

function Login({ onLogin }: { onLogin: (user: User) => void }) {
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);
  async function submit(event: React.FormEvent) {
    event.preventDefault(); setLoading(true); setError("");
    try {
      const email = firebaseEmailForUsername(username);
      if (!email) throw new Error("Usa uno dei profili autorizzati: viterbo, gran-sasso o admin.");
      const credential = await signInWithEmailAndPassword(firebaseAuth, email, password);
      const response = await readJson(await establishServerSession(credential.user));
      setPassword("");
      onLogin(response.user as User);
    }
    catch (reason) {
      const code = (reason as { code?: string }).code ?? "";
      setError(code.startsWith("auth/") ? "Nome utente o password non validi." : reason instanceof Error ? reason.message : "Accesso non riuscito.");
    }
    finally { setLoading(false); }
  }
  return <main className="login-page"><section className="login-card"><div className="brand-mark">MS</div><p className="eyebrow">ACCESSO FIREBASE PROTETTO</p><h1>Gestionale di<br />Marinelli Stefano</h1><p className="muted">Accedi con <strong>viterbo</strong>, <strong>gran-sasso</strong> oppure <strong>admin</strong>. L’indirizzo tecnico viene aggiunto automaticamente e la password resta gestita da Firebase.</p><form onSubmit={submit} className="stack"><ClearableInput label="Nome utente" autoComplete="username" value={username} onChange={setUsername} placeholder="viterbo, gran-sasso o admin" spellCheck={false} required /><ClearableInput label="Password" type="password" autoComplete="current-password" value={password} onChange={setPassword} placeholder="Inserisci la password Firebase" required />{error && <div className="alert danger">{error}</div>}<button className="primary big" disabled={loading}>{loading ? "Accesso sicuro…" : "Accedi"}</button></form><div className="login-security"><i /><span>Autenticazione e sessione protette da Firebase</span></div></section></main>;
}

function CustomerForm({ store, onSaved, onClose, customer = null }: { store: Store; onSaved: () => Promise<void>; onClose: () => void; customer?: Customer | null }) {
  const [form, setForm] = useState({ customerType: customer?.customerType ?? "private" as "private" | "company", firstName: customer?.firstName ?? "", lastName: customer?.lastName ?? "", companyName: customer?.companyName ?? "", vatNumber: customer?.vatNumber ?? "", pec: customer?.pec ?? "", sdiCode: customer?.sdiCode ?? "", phone: customer?.phone ?? "", email: customer?.email ?? "", address: customer?.address ?? "", postalCode: customer?.postalCode ?? "", city: customer?.city ?? "", province: customer?.province ?? "", taxCode: customer?.taxCode ?? "" });
  const [error, setError] = useState("");
  const set = (name: keyof typeof form) => (value: string) => setForm((current) => ({ ...current, [name]: value }));
  async function save(event: React.FormEvent) { event.preventDefault(); setError(""); try { await post(customer ? "updateCustomer" : "createCustomer", { ...form, store, id: customer?.id }); await onSaved(); onClose(); } catch (reason) { setError(reason instanceof Error ? reason.message : "Errore."); } }
  return <form className="stack" onSubmit={save}><div className="customer-type-tabs"><button type="button" className={form.customerType === "private" ? "active" : ""} onClick={() => setForm((current) => ({ ...current, customerType: "private" }))}>Privato</button><button type="button" className={form.customerType === "company" ? "active" : ""} onClick={() => setForm((current) => ({ ...current, customerType: "company" }))}>Azienda / Società</button></div><div className="form-grid">{form.customerType === "private" ? <><ClearableInput label="Nome" value={form.firstName} onChange={set("firstName")} required /><ClearableInput label="Cognome" value={form.lastName} onChange={set("lastName")} required /><ClearableInput className="full" label="Codice fiscale" value={form.taxCode} onChange={set("taxCode")} /></> : <><ClearableInput className="full" label="Ragione sociale" value={form.companyName} onChange={set("companyName")} required /><ClearableInput label="Partita IVA" value={form.vatNumber} onChange={set("vatNumber")} required /><ClearableInput label="Codice fiscale società" value={form.taxCode} onChange={set("taxCode")} /><ClearableInput label="PEC" type="email" value={form.pec} onChange={set("pec")} /><ClearableInput label="Codice SDI" value={form.sdiCode} onChange={set("sdiCode")} /><ClearableInput label="Nome referente" value={form.firstName} onChange={set("firstName")} /><ClearableInput label="Cognome referente" value={form.lastName} onChange={set("lastName")} /></>}<ClearableInput label="Telefono" value={form.phone} onChange={set("phone")} /><ClearableInput label="Email" type="email" value={form.email} onChange={set("email")} /><ClearableInput className="full" label="Indirizzo" value={form.address} onChange={set("address")} /><ClearableInput label="CAP" value={form.postalCode} onChange={set("postalCode")} /><ClearableInput label="Comune" value={form.city} onChange={set("city")} /><ClearableInput label="Provincia" value={form.province} onChange={set("province")} maxLength={2} />{error && <div className="alert danger full">{error}</div>}<div className="form-actions full"><button type="button" className="secondary" onClick={onClose}>Annulla</button><button className="primary">{customer ? "Salva modifiche" : `Salva ${form.customerType === "company" ? "azienda" : "privato"}`}</button></div></div></form>;
}

function ProductSearch({ products, store, onAdd, compact = false }: { products: Product[]; store: Store; onAdd: (product: Product) => void; compact?: boolean }) {
  const [query, setQuery] = useState("");
  const results = useMemo(() => {
    const normalized = query.trim().toLocaleLowerCase("it");
    if (!normalized && compact) return [];
    return groupProducts(products).filter((group) => !normalized || `${group.brand} ${group.name} ${group.category}`.toLocaleLowerCase("it").includes(normalized) || group.variants.some((variant) => searchableProduct(variant).includes(normalized))).slice(0, 8);
  }, [products, query, compact]);
  function onKeyDown(event: React.KeyboardEvent<HTMLInputElement>) { if (event.key !== "Enter") return; event.preventDefault(); const exact = products.find((product) => product.eans.split(",").includes(query.trim())); if (exact) { onAdd(exact); setQuery(""); } }
  return <div className="product-search"><ClearableInput label={compact ? undefined : "EAN, marca, prodotto, colore o taglia"} value={query} onChange={setQuery} onKeyDown={onKeyDown} placeholder="Scansiona EAN o cerca prodotto…" autoFocus={!compact} /><div className={`search-results grouped ${compact ? "compact" : ""}`}>{results.map((group) => { const normalized = query.trim().toLocaleLowerCase("it"); const groupMatch = !normalized || `${group.brand} ${group.name} ${group.category}`.toLocaleLowerCase("it").includes(normalized); const visibleVariants = groupMatch ? group.variants : group.variants.filter((variant) => searchableProduct(variant).includes(normalized)); return <article className="product-group-result" key={group.key}><div className="product-group-result-head"><span><strong>{group.brand ? `${group.brand} · ` : ""}{group.name}</strong><small>{group.category || "Senza categoria"}</small></span><span className="count-pill">{group.variants.length} {group.variants.length === 1 ? "variante" : "varianti"}</span></div><div className="variant-choice-list">{visibleVariants.map((variant) => { const available = store === "Viterbo" ? variant.viterboQty - variant.viterboReserved : variant.granSassoQty - variant.granSassoReserved; return <button type="button" className="variant-choice" key={variant.id} onClick={() => { onAdd(variant); setQuery(""); }}><span><strong>{variant.color} · {variant.size}</strong><small>{variant.sku}{variant.eans ? ` · ${variant.eans.split(",").join(" · ")}` : ""}</small></span><span className={available <= 0 ? "stock-zero" : "stock-ok"}>{available} disp.</span><b>{money(variant.price)}</b></button>; })}</div></article>; })}</div></div>;
}

function GiftDraft({ onAdd, onClose }: { onAdd: (item: CartItem) => void; onClose: () => void }) {
  const [beneficiary, setBeneficiary] = useState(""); const [amount, setAmount] = useState(""); const [expiresAt, setExpiresAt] = useState(todayPlusYear());
  return <Modal title="Aggiungi buono regalo al carrello" onClose={onClose}><form className="stack" onSubmit={(event) => { event.preventDefault(); const value = Number(amount); if (value <= 0) return; onAdd({ key: keyId(), productId: null, description: `Buono regalo · ${beneficiary || "Non indicato"}`, quantity: 1, unitPrice: value, itemType: "gift", metadata: { beneficiary: beneficiary || "Non indicato", expiresAt, code: makeEan13() } }); }}><p className="muted">Il buono sarà creato soltanto quando completi la vendita e scegli il pagamento.</p><ClearableInput label="Persona intestataria" value={beneficiary} onChange={setBeneficiary} placeholder="Facoltativo" /><ClearableInput label="Valore" type="number" step="0.01" value={amount} onChange={setAmount} required /><ClearableInput label="Scadenza" type="date" value={expiresAt} onChange={setExpiresAt} required /><div className="form-actions"><button type="button" className="secondary" onClick={onClose}>Annulla</button><button className="primary">Aggiungi al carrello</button></div></form></Modal>;
}

function SimpleDraft({ title, defaultDescription, onAdd, onClose }: { title: string; defaultDescription: string; onAdd: (item: CartItem) => void; onClose: () => void }) {
  const [description, setDescription] = useState(defaultDescription); const [amount, setAmount] = useState("");
  return <Modal title={title} onClose={onClose}><form className="stack" onSubmit={(event) => { event.preventDefault(); const value = Number(amount); if (!description || value === 0) return; onAdd({ key: keyId(), productId: null, description, quantity: 1, unitPrice: value, itemType: "service", metadata: {} }); }}><ClearableInput label="Descrizione" value={description} onChange={setDescription} required /><ClearableInput label="Importo" type="number" step="0.01" value={amount} onChange={setAmount} required /><div className="form-actions"><button type="button" className="secondary" onClick={onClose}>Annulla</button><button className="primary">Aggiungi al carrello</button></div></form></Modal>;
}

function DepositDraft({ title, products, kind, onAdd, onClose }: { title: string; products: Product[]; kind: "product" | "repair"; onAdd: (item: CartItem) => void; onClose: () => void }) {
  const [description, setDescription] = useState(kind === "repair" ? "Risolatura" : ""); const [productId, setProductId] = useState(""); const [total, setTotal] = useState(""); const [deposit, setDeposit] = useState("");
  const product = products.find((item) => item.id === Number(productId));
  return <Modal title={title} onClose={onClose}><form className="stack" onSubmit={(event) => { event.preventDefault(); const totalPrice = Number(total); const depositValue = Number(deposit); if (!description || totalPrice <= 0 || depositValue < 0 || depositValue > totalPrice) return; const isDeposit = depositValue > 0 && depositValue < totalPrice; onAdd({ key: keyId(), productId: product?.id ?? null, description: isDeposit ? `Acconto ${description}` : description, quantity: 1, unitPrice: isDeposit ? depositValue : totalPrice, itemType: isDeposit ? (kind === "repair" ? "repair_deposit" : "deposit") : "service", metadata: isDeposit ? { totalPrice, productId: product?.id ?? null, code: makeEan13() } : {} }); }}><p className="muted">Se inserisci un acconto inferiore al totale verrà generato un PDF con EAN per il saldo al ritiro.</p>{products.length > 0 && <label className="field"><span>Prodotto da prenotare</span><select value={productId} onChange={(event) => { setProductId(event.target.value); const selected = products.find((item) => item.id === Number(event.target.value)); if (selected) { setDescription(`${selected.name} · ${selected.color} ${selected.size}`); setTotal(String(selected.price)); } }}><option value="">Seleziona prodotto</option>{products.map((item) => <option key={item.id} value={item.id}>{item.name} · {item.color} {item.size}</option>)}</select></label>}<ClearableInput label="Descrizione" value={description} onChange={setDescription} required /><ClearableInput label="Totale concordato" type="number" step="0.01" value={total} onChange={setTotal} required /><ClearableInput label="Acconto (0 per vendita completa)" type="number" step="0.01" value={deposit} onChange={setDeposit} /><div className="form-actions"><button type="button" className="secondary" onClick={onClose}>Annulla</button><button className="primary">Aggiungi al carrello</button></div></form></Modal>;
}

function ReturnDraft({ products, store, onAdd, onClose }: { products: Product[]; store: Store; onAdd: (item: CartItem) => void; onClose: () => void }) {
  const [query, setQuery] = useState(""); const [productId, setProductId] = useState(""); const [amount, setAmount] = useState(""); const [receipt, setReceipt] = useState("");
  const matches = products.filter((product) => `${product.name} ${product.sku} ${product.eans}`.toLowerCase().includes(query.toLowerCase())).slice(0, 6);
  const selected = products.find((product) => product.id === Number(productId));
  return <Modal title="Reso o cambio merce" onClose={onClose}><form className="stack" onSubmit={(event) => { event.preventDefault(); if (!selected || Number(amount) <= 0) return; onAdd({ key: keyId(), productId: selected.id, description: `Reso ${selected.name} · ${selected.color} ${selected.size}`, quantity: -1, unitPrice: Number(amount), itemType: "return", metadata: { originalReceipt: receipt, store } }); }}><p className="muted">Il prodotto rientra in magazzino e il suo importo viene sottratto. Puoi poi aggiungere il prodotto sostitutivo al carrello.</p><ClearableInput label="Scontrino originale" value={receipt} onChange={setReceipt} /><ClearableInput label="Cerca prodotto restituito" value={query} onChange={setQuery} />{matches.length > 0 && <div className="choice-list">{matches.map((item) => <button type="button" className={item.id === Number(productId) ? "selected" : ""} key={item.id} onClick={() => { setProductId(String(item.id)); setAmount(String(item.price)); setQuery(`${item.name} ${item.color} ${item.size}`); }}>{item.name} · {item.color} {item.size}</button>)}</div>}<ClearableInput label="Importo da stornare" type="number" step="0.01" value={amount} onChange={setAmount} required /><div className="form-actions"><button type="button" className="secondary" onClick={onClose}>Annulla</button><button className="primary">Aggiungi reso al carrello</button></div></form></Modal>;
}

// Versione storica mantenuta temporaneamente come riferimento per le altre sezioni operative.
// eslint-disable-next-line @typescript-eslint/no-unused-vars
function CashRegister({ data, reload }: { data: Bootstrap; reload: () => Promise<void> }) {
  const [adminStore, setAdminStore] = useState<Store>("Viterbo");
  const store = data.user.store ?? adminStore;
  const [cart, setCart] = useState<CartItem[]>([]); const [customer, setCustomer] = useState<Customer | null>(null); const [customerQuery, setCustomerQuery] = useState(""); const [modal, setModal] = useState<string | null>(null); const [notice, setNotice] = useState(""); const [error, setError] = useState(""); const [totalOverride, setTotalOverride] = useState(""); const [payment, setPayment] = useState("cash"); const [cashAmount, setCashAmount] = useState(""); const [cardAmount, setCardAmount] = useState(""); const [giftCode, setGiftCode] = useState(""); const [giftAmount, setGiftAmount] = useState(""); const [lastSale, setLastSale] = useState<{ id: number; receiptNo: string } | null>(null);
  const subtotal = useMemo(() => Math.round(cart.reduce((sum, item) => sum + item.quantity * item.unitPrice, 0) * 100) / 100, [cart]);
  const total = totalOverride === "" ? subtotal : Number(totalOverride) || 0;
  const matchingCustomers = useMemo(() => { const q = customerQuery.trim().toLocaleLowerCase("it"); return q ? data.customers.filter((item) => `${customerLabel(item)} ${item.vatNumber}`.toLocaleLowerCase("it").includes(q)).slice(0, 8) : []; }, [data.customers, customerQuery]);
  function addProduct(product: Product) { setCart((current) => { const existing = current.find((item) => item.productId === product.id && item.itemType === "product"); return existing ? current.map((item) => item.key === existing.key ? { ...item, quantity: item.quantity + 1 } : item) : [...current, { key: keyId(), productId: product.id, description: `${product.name} · ${product.color} ${product.size}`, quantity: 1, unitPrice: product.price, itemType: "product", metadata: {} }]; }); setNotice(`${product.name} aggiunto al carrello.`); setTimeout(() => setNotice(""), 2200); }
  function updateItem(key: string, change: Partial<CartItem>) { setCart((current) => current.map((item) => item.key === key ? { ...item, ...change } : item)); setTotalOverride(""); }
  function removeItem(key: string) { setCart((current) => current.filter((item) => item.key !== key)); setTotalOverride(""); }
  async function scanSpecial(code: string) { setError(""); try { const result = await readJson(await fetch(`/api/data?view=code&q=${encodeURIComponent(code)}`)); if (result.kind === "gift") { setGiftCode(result.record.code); setPayment("gift"); setNotice(`Buono riconosciuto: saldo ${money(result.record.balance)}`); } if (result.kind === "reservation") { if (result.record.status !== "open") throw new Error("Questa prenotazione risulta già chiusa."); if (result.record.store !== store) throw new Error(`Prenotazione emessa da ${result.record.store}.`); setCart((current) => [...current, { key: keyId(), productId: null, description: `Saldo: ${result.record.description}`, quantity: 1, unitPrice: result.record.balanceDue, itemType: "reservation_balance", locked: true, metadata: { code: result.record.code } }]); setNotice("Saldo prenotazione aggiunto al carrello."); } } catch (reason) { setError(reason instanceof Error ? reason.message : "Codice non trovato."); } }
  function preparePayments() { if (payment === "cash") return { cashAmount: total, cardAmount: 0, giftAmount: 0, giftCodeUsed: "" }; if (payment === "card") return { cashAmount: 0, cardAmount: total, giftAmount: 0, giftCodeUsed: "" }; if (payment === "mixed") return { cashAmount: Number(cashAmount) || 0, cardAmount: Number(cardAmount) || 0, giftAmount: 0, giftCodeUsed: "" }; const gift = Number(giftAmount) || 0; return { cashAmount: Number(cashAmount) || Math.max(0, total - gift), cardAmount: Number(cardAmount) || 0, giftAmount: gift, giftCodeUsed: giftCode }; }
  async function completeSale() { setError(""); setNotice(""); try { const result = await post("createSale", { store, customerId: customer?.id ?? null, items: cart, total, ...preparePayments() }); setLastSale({ id: result.saleId, receiptNo: result.receiptNo }); setCart([]); setTotalOverride(""); setCashAmount(""); setCardAmount(""); setGiftAmount(""); setGiftCode(""); setCustomer(null); setCustomerQuery(""); setNotice(`Vendita ${result.receiptNo} registrata. ${result.realtimeSynced ? "Sincronizzata in tempo reale." : result.realtimeWarning ?? "Sincronizzazione Firebase in attesa."} Richiesta scontrino pronta.`); await reload(); } catch (reason) { const extended = reason as Error & { data?: { insufficient?: string[] } }; setError(`${extended.message}${extended.data?.insufficient?.length ? `: ${extended.data.insufficient.join(", ")}` : ""}`); } }
  return <section className="screen"><div className="screen-head"><div><p className="eyebrow">POSTAZIONE OPERATIVA</p><h1>Cassa {store}</h1></div>{data.user.role === "admin" && <label className="field inline"><span>Negozio</span><select value={adminStore} onChange={(event) => setAdminStore(event.target.value as Store)}><option>Viterbo</option><option>Gran Sasso</option></select></label>}</div>{notice && <div className="alert success">{notice}</div>}{error && <div className="alert danger">{error}</div>}<div className="cash-grid"><div className="cash-main"><div className="panel"><div className="panel-title"><div><p className="eyebrow">RICERCA RAPIDA</p><h2>Scansiona o cerca</h2></div><ClearableInput compact label="Codice buono/acconto" value={giftCode} onChange={setGiftCode} onKeyDown={(event) => { if (event.key === "Enter") { event.preventDefault(); void scanSpecial(giftCode); } }} placeholder="Scansiona EAN documento" /></div><ProductSearch products={data.products} store={store} onAdd={addProduct} /></div><div className="panel"><div className="panel-title"><div><p className="eyebrow">CLIENTE</p><h2>{customer ? customerLabel(customer) : "Associa per nominativo"}</h2></div>{customer && <button className="text-button" onClick={() => setCustomer(null)}>Rimuovi</button>}</div><ClearableInput value={customerQuery} onChange={setCustomerQuery} placeholder="Nome, società o P.IVA…" />{matchingCustomers.length > 0 && <div className="customer-dropdown">{matchingCustomers.map((item) => <button key={item.id} onClick={() => { setCustomer(item); setCustomerQuery(""); }}><strong>{customerLabel(item)}</strong><small>{item.vatNumber || item.city || item.phone || item.scope}</small></button>)}</div>}</div><div className="actions-strip"><button onClick={() => setModal("customer")}>＋<span>Nuovo cliente</span></button><button onClick={() => setModal("gift")}>🎁<span>Buono regalo</span></button><button onClick={() => setModal("varie")}>＋<span>Varie</span></button>{store === "Viterbo" ? <button onClick={() => setModal("repair")}>↗<span>Risolatura</span></button> : <button onClick={() => setModal("shirt")}>◫<span>Maglie Gran Sasso</span></button>}<button onClick={() => setModal("reservation")}>▣<span>Prenotazione</span></button><button onClick={() => setModal("return")}>↩<span>Reso / cambio</span></button></div><div className="panel cart-panel"><div className="panel-title"><div><p className="eyebrow">VENDITA</p><h2>Carrello</h2></div><span className="count-pill">{cart.length} righe</span></div>{!cart.length ? <Empty>Scansiona un EAN oppure usa uno dei pulsanti operativi.</Empty> : <div className="cart-list">{cart.map((item) => <div className={`cart-row ${item.itemType === "return" ? "return-row" : ""}`} key={item.key}><div className="cart-desc"><strong>{item.description}</strong><small>{item.itemType.replaceAll("_", " ")}</small></div><ClearableInput compact aria-label="Quantità" type="number" step="1" value={item.quantity} onChange={(value) => updateItem(item.key, { quantity: Number(value) || 0 })} disabled={item.locked} /><ClearableInput compact aria-label="Prezzo unitario" type="number" step="0.01" value={item.unitPrice} onChange={(value) => updateItem(item.key, { unitPrice: Number(value) || 0 })} disabled={item.locked} /><b>{money(item.quantity * item.unitPrice)}</b><button className="icon-button" onClick={() => removeItem(item.key)} aria-label="Rimuovi">×</button></div>)}</div>}</div></div><aside className="checkout"><div><p className="eyebrow">RIEPILOGO</p><div className="total-line"><span>Subtotale</span><b>{money(subtotal)}</b></div><ClearableInput label="Totale vendita modificabile" type="number" step="0.01" value={totalOverride} onChange={setTotalOverride} placeholder={subtotal.toFixed(2)} /><div className="grand-total"><span>Totale</span><strong>{money(total)}</strong></div></div><div><p className="eyebrow">PAGAMENTO</p><div className="payment-tabs">{[["cash","Contanti"],["card","Carta"],["mixed","Misto"],["gift","Buono"]].map(([value,label]) => <button key={value} className={payment === value ? "active" : ""} onClick={() => setPayment(value)}>{label}</button>)}</div>{payment === "mixed" && <div className="split-fields"><ClearableInput label="Contanti" type="number" step="0.01" value={cashAmount} onChange={setCashAmount} /><ClearableInput label="Carta" type="number" step="0.01" value={cardAmount} onChange={setCardAmount} /></div>}{payment === "gift" && <div className="stack compact-stack"><ClearableInput label="Codice EAN buono" value={giftCode} onChange={setGiftCode} onKeyDown={(event) => { if (event.key === "Enter") { event.preventDefault(); void scanSpecial(giftCode); } }} /><ClearableInput label="Importo da scalare" type="number" step="0.01" value={giftAmount} onChange={setGiftAmount} /><ClearableInput label="Residuo contanti" type="number" step="0.01" value={cashAmount} onChange={setCashAmount} /><ClearableInput label="Residuo carta" type="number" step="0.01" value={cardAmount} onChange={setCardAmount} /></div>}</div><button className="primary checkout-button" disabled={!cart.length} onClick={completeSale}>Completa e stampa scontrino · {money(total)}</button>{lastSale && <div className="last-sale"><strong>Vendita {lastSale.receiptNo}</strong><a className="secondary" href={`/api/pdf?type=courtesy&id=${lastSale.id}`}>Scontrino cortesia PDF</a><a className="text-button" href={`/api/pdf?type=receipt&id=${lastSale.id}`}>Scontrino interno</a></div>}<p className="fine-print">Ogni incasso crea una vendita e una richiesta di scontrino fiscale.</p></aside></div>{modal === "customer" && <Modal title="Nuovo cliente" onClose={() => setModal(null)}><CustomerForm store={store} onSaved={reload} onClose={() => setModal(null)} /></Modal>}{modal === "gift" && <GiftDraft onAdd={(item) => { setCart((current) => [...current, item]); setModal(null); }} onClose={() => setModal(null)} />}{modal === "varie" && <SimpleDraft title="Vendita varie" defaultDescription="Varie" onAdd={(item) => { setCart((current) => [...current, item]); setModal(null); }} onClose={() => setModal(null)} />}{modal === "shirt" && <SimpleDraft title="Maglie Gran Sasso" defaultDescription="Maglie Gran Sasso" onAdd={(item) => { setCart((current) => [...current, item]); setModal(null); }} onClose={() => setModal(null)} />}{modal === "repair" && <DepositDraft title="Risolatura" products={[]} kind="repair" onAdd={(item) => { setCart((current) => [...current, item]); setModal(null); }} onClose={() => setModal(null)} />}{modal === "reservation" && <DepositDraft title="Prenotazione prodotto" products={data.products} kind="product" onAdd={(item) => { setCart((current) => [...current, item]); setModal(null); }} onClose={() => setModal(null)} />}{modal === "return" && <ReturnDraft products={data.products} store={store} onAdd={(item) => { setCart((current) => [...current, item]); setModal(null); }} onClose={() => setModal(null)} />}</section>;
}

function Customers({ data, reload }: { data: Bootstrap; reload: () => Promise<void> }) {
  const [query, setQuery] = useState(""); const [section, setSection] = useState<"private" | "company">("private"); const [selected, setSelected] = useState<Customer | null>(null); const [history, setHistory] = useState<{ sales: Sale[]; items: { saleId: number; description: string; quantity: number; lineTotal: number }[] } | null>(null); const [newOpen, setNewOpen] = useState(false);
  const visible = useMemo(() => { const q = query.toLocaleLowerCase("it"); return data.customers.filter((item) => item.customerType === section && (!q || `${customerLabel(item)} ${item.vatNumber} ${item.taxCode} ${item.city}`.toLocaleLowerCase("it").includes(q))); }, [data.customers, query, section]);
  async function openCustomer(customer: Customer) { setSelected(customer); const result = await readJson(await fetch(`/api/data?view=customer&id=${customer.id}`)); setHistory(result); }
  return <section className="screen"><div className="screen-head"><div><p className="eyebrow">ANAGRAFICHE E STORICO</p><h1>Clienti</h1></div><button className="primary" onClick={() => setNewOpen(true)}>＋ Nuovo cliente</button></div><div className="panel"><div className="customer-type-tabs section-tabs"><button className={section === "private" ? "active" : ""} onClick={() => { setSection("private"); setSelected(null); setHistory(null); }}>Privati <b>{data.customers.filter((item) => item.customerType === "private").length}</b></button><button className={section === "company" ? "active" : ""} onClick={() => { setSection("company"); setSelected(null); setHistory(null); }}>Aziende e società <b>{data.customers.filter((item) => item.customerType === "company").length}</b></button></div><ClearableInput label={section === "company" ? "Ricerca ragione sociale, P.IVA o comune" : "Ricerca per nominativo"} value={query} onChange={setQuery} placeholder={section === "company" ? "Ragione sociale o P.IVA…" : "Nome o cognome…"} /><div className="scope-row"><span>Viterbo <b>{visible.filter((item) => item.scope === "Viterbo").length}</b></span><span>Gran Sasso <b>{visible.filter((item) => item.scope === "Gran Sasso").length}</b></span><span>Comuni <b>{visible.filter((item) => item.scope === "Comune").length}</b></span></div></div><div className="two-columns"><div className="panel list-panel">{visible.length ? visible.map((customer) => <button className={`customer-card ${selected?.id === customer.id ? "selected" : ""}`} key={customer.id} onClick={() => void openCustomer(customer)}><span><strong>{customerLabel(customer)}</strong><small>{customer.customerType === "company" ? `P.IVA ${customer.vatNumber || "non indicata"} · ${customer.city || "sede non indicata"}` : customer.city || customer.phone || "Nessun recapito"}</small></span><span className="scope-badge">{customer.scope}</span></button>) : <Empty>Nessuna anagrafica trovata.</Empty>}</div><div className="panel detail-panel">{!selected || !history ? <Empty>Seleziona un cliente per vedere dati e vendite già effettuate.</Empty> : <><div className="panel-title"><div><p className="eyebrow">{selected.customerType === "company" ? "AZIENDA / SOCIETÀ" : "CLIENTE PRIVATO"}</p><h2>{customerLabel(selected)}</h2></div><span className="scope-badge">{selected.scope}</span></div>{selected.customerType === "company" && <div className="company-detail"><span><small>Partita IVA</small><strong>{selected.vatNumber || "—"}</strong></span><span><small>PEC</small><strong>{selected.pec || "—"}</strong></span><span><small>Codice SDI</small><strong>{selected.sdiCode || "—"}</strong></span><span><small>Sede</small><strong>{[selected.address, selected.postalCode, selected.city, selected.province].filter(Boolean).join(" · ") || "—"}</strong></span></div>}{history.sales.length ? history.sales.map((sale) => <article className="history-sale" key={sale.id}><div><strong>{sale.receiptNo}</strong><small>{dateTime(sale.createdAt)} · {sale.store}</small></div><b className={sale.total < 0 ? "negative" : ""}>{money(sale.total)}</b><a className="secondary small" href={`/api/pdf?type=receipt&id=${sale.id}`}>Stampa scontrino interno</a><ul>{history.items.filter((item) => item.saleId === sale.id).map((item, index) => <li key={`${sale.id}-${index}`}>{item.quantity} × {item.description} <span>{money(item.lineTotal)}</span></li>)}</ul></article>) : <Empty>Nessuna vendita associata.</Empty>}</>}</div></div>{newOpen && <Modal title="Nuova anagrafica" onClose={() => setNewOpen(false)}><CustomerForm store={data.user.store ?? "Viterbo"} onSaved={reload} onClose={() => setNewOpen(false)} /></Modal>}</section>;
}

function Inventory({ data }: { data: Bootstrap }) {
  const [query, setQuery] = useState("");
  const groups = useMemo(() => {
    const normalized = query.trim().toLocaleLowerCase("it");
    return groupProducts(data.products).filter((group) => !normalized || `${group.brand} ${group.name} ${group.category}`.toLocaleLowerCase("it").includes(normalized) || group.variants.some((variant) => searchableProduct(variant).includes(normalized)));
  }, [data.products, query]);
  const totalViterbo = groups.reduce((sum, group) => sum + group.variants.reduce((variantSum, variant) => variantSum + variant.viterboQty - variant.viterboReserved, 0), 0);
  const totalGranSasso = groups.reduce((sum, group) => sum + group.variants.reduce((variantSum, variant) => variantSum + variant.granSassoQty - variant.granSassoReserved, 0), 0);
  return <section className="screen"><div className="screen-head"><div><p className="eyebrow">DISPONIBILITÀ DEI DUE NEGOZI</p><h1>Magazzini</h1><p className="muted inventory-intro">Le varianti sono ordinate prima per colore e poi per taglia crescente. La disponibilità di Viterbo e Gran Sasso è sempre affiancata.</p></div></div><div className="panel"><ClearableInput label="Ricerca rapida per marca, prodotto, colore, taglia o EAN" value={query} onChange={setQuery} placeholder="Esempio: Scarpa, nero, 42 o codice EAN…" /><div className="scope-row"><span>Viterbo <b>{totalViterbo}</b></span><span>Gran Sasso <b>{totalGranSasso}</b></span><span>Prodotti <b>{groups.length}</b></span></div></div><div className="panel warehouse-panel inventory-all-stores"><div className="inventory-groups">{groups.length ? groups.map((group) => { const firstPhoto = group.variants.find((variant) => variant.photoKey); const availableViterbo = group.variants.reduce((sum, variant) => sum + variant.viterboQty - variant.viterboReserved, 0); const availableGranSasso = group.variants.reduce((sum, variant) => sum + variant.granSassoQty - variant.granSassoReserved, 0); return <article className="inventory-group" key={group.key}><div className="inventory-group-head dual-store">{firstPhoto?.photoKey ? <img className="product-thumb large" src={`/api/products?key=${encodeURIComponent(firstPhoto.photoKey)}`} alt={`${group.name} ${firstPhoto.color}`} /> : <span className="photo-placeholder large">—</span>}<span className="inventory-group-title"><strong>{group.brand ? `${group.brand} · ` : ""}{group.name}</strong><small>{group.category || "Senza categoria"} · {group.variants.length} {group.variants.length === 1 ? "variante" : "varianti"}</small></span><span className="inventory-store-totals"><b>VT {availableViterbo}</b><b>GS {availableGranSasso}</b></span></div><div className="table-wrap"><table className="variant-table dual-store-table"><thead><tr><th>Foto</th><th>Colore</th><th>Taglia ↑</th><th>SKU</th><th>EAN</th><th>Viterbo</th><th>Gran Sasso</th></tr></thead><tbody>{group.variants.map((variant) => { const viterbo = variant.viterboQty - variant.viterboReserved; const granSasso = variant.granSassoQty - variant.granSassoReserved; return <tr key={variant.id}><td>{variant.photoKey ? <img className="product-thumb" src={`/api/products?key=${encodeURIComponent(variant.photoKey)}`} alt={`${group.name} ${variant.color}`} /> : <span className="photo-placeholder">—</span>}</td><td><strong>{variant.color}</strong></td><td><strong>{variant.size}</strong></td><td>{variant.sku}</td><td>{variant.eans.split(",").join(" · ")}</td><td><span className={viterbo <= 0 ? "store-stock danger" : "store-stock"}>{viterbo} disp.</span></td><td><span className={granSasso <= 0 ? "store-stock danger" : "store-stock"}>{granSasso} disp.</span></td></tr>; })}</tbody></table></div></article>; }) : <Empty>Nessun prodotto trovato.</Empty>}</div></div></section>;
}

function ReorderList({ data }: { data: Bootstrap }) {
  const [store, setStore] = useState<"Tutti" | Store>("Tutti");
  const [query, setQuery] = useState("");
  const variants = useMemo(() => data.products.filter((product) => {
    const viterbo = product.viterboQty - product.viterboReserved;
    const granSasso = product.granSassoQty - product.granSassoReserved;
    const isLow = store === "Viterbo" ? viterbo <= 2 : store === "Gran Sasso" ? granSasso <= 2 : viterbo <= 2 || granSasso <= 2;
    return isLow && searchableProduct(product).includes(query.trim().toLocaleLowerCase("it"));
  }).sort((left, right) => variantCollator.compare(`${left.brand} ${left.name}`, `${right.brand} ${right.name}`) || variantCollator.compare(left.color, right.color) || variantCollator.compare(left.size, right.size)), [data.products, query, store]);
  return <section className="screen"><div className="screen-head"><div><p className="eyebrow">SOLO AMMINISTRAZIONE</p><h1>Articoli da riordinare</h1><p className="muted inventory-intro">Sono evidenziate le varianti con 2 pezzi disponibili o meno in almeno un negozio.</p></div><label className="field inline"><span>Negozio</span><select value={store} onChange={(event) => setStore(event.target.value as "Tutti" | Store)}><option>Tutti</option><option>Viterbo</option><option>Gran Sasso</option></select></label></div><div className="metric-grid"><Metric label="Varianti da riordinare" value={String(variants.length)} note={store === "Tutti" ? "nei due negozi" : `a ${store}`} /><Metric label="Esaurite a Viterbo" value={String(variants.filter((item) => item.viterboQty - item.viterboReserved <= 0).length)} /><Metric label="Esaurite a Gran Sasso" value={String(variants.filter((item) => item.granSassoQty - item.granSassoReserved <= 0).length)} /></div><div className="panel"><ClearableInput label="Cerca marca, modello, colore, taglia o EAN" value={query} onChange={setQuery} /><div className="table-wrap"><table className="reorder-table"><thead><tr><th>Prodotto</th><th>Colore</th><th>Taglia</th><th>SKU / EAN</th><th>Viterbo</th><th>Gran Sasso</th><th>Priorità</th></tr></thead><tbody>{variants.map((variant) => { const viterbo = variant.viterboQty - variant.viterboReserved; const granSasso = variant.granSassoQty - variant.granSassoReserved; const urgent = viterbo <= 0 || granSasso <= 0; return <tr key={variant.id} className={urgent ? "reorder-urgent" : ""}><td><strong>{variant.brand ? `${variant.brand} · ` : ""}{variant.name}</strong></td><td>{variant.color}</td><td><strong>{variant.size}</strong></td><td>{variant.sku}<small>{variant.eans.split(",").join(" · ")}</small></td><td><b className={viterbo <= 2 ? "negative" : ""}>{viterbo}</b></td><td><b className={granSasso <= 2 ? "negative" : ""}>{granSasso}</b></td><td><span className={`status ${urgent ? "reorder-now" : "reorder-soon"}`}>{urgent ? "Riordino urgente" : "Scorta bassa"}</span></td></tr>; })}</tbody></table></div>{!variants.length && <Empty>Nessun articolo da riordinare con questi filtri.</Empty>}</div></section>;
}

function Transfers({ data, reload }: { data: Bootstrap; reload: () => Promise<void> }) {
  const [fromStore, setFromStore] = useState<Store>(data.user.store ?? "Viterbo"); const [items, setItems] = useState<CartItem[]>([]); const [sender, setSender] = useState(""); const [receiver, setReceiver] = useState(""); const [carrier, setCarrier] = useState(""); const [reason, setReason] = useState("Trasferimento merce"); const [error, setError] = useState(""); const [last, setLast] = useState<{ id: number; code: string } | null>(null);
  function add(product: Product) { if (items.some((item) => item.productId === product.id)) return; setItems((current) => [...current, { key: keyId(), productId: product.id, description: `${product.name} · ${product.color} ${product.size}`, quantity: 1, unitPrice: 0, itemType: "transfer", metadata: {} }]); }
  const insufficients = items.filter((item) => { const product = data.products.find((row) => row.id === item.productId); if (!product) return true; const available = fromStore === "Viterbo" ? product.viterboQty - product.viterboReserved : product.granSassoQty - product.granSassoReserved; return item.quantity > available; });
  async function submit() { setError(""); try { const result = await post("createTransfer", { fromStore, items, sender, receiver, carrier, transportReason: reason }); setLast({ id: result.transferId, code: result.code }); setItems([]); await reload(); } catch (reasonValue) { const extended = reasonValue as Error & { data?: { insufficient?: { description: string; available: number }[] } }; setError(`${extended.message}${extended.data?.insufficient?.length ? ` ${extended.data.insufficient.map((row) => `${row.description}: disponibili ${row.available}`).join("; ")}` : ""}`); } }
  return <section className="screen"><div className="screen-head"><div><p className="eyebrow">MOVIMENTO MULTIPRODOTTO</p><h1>Trasferimenti e DDT</h1></div></div>{error && <div className="alert danger visual-alert">⚠ {error}</div>}{insufficients.length > 0 && <div className="alert danger visual-alert">⚠ Giacenza insufficiente per {insufficients.map((item) => item.description).join(", ")}.</div>}<div className="transfer-grid"><div className="panel"><label className="field"><span>Magazzino di partenza</span><select value={fromStore} disabled={data.user.role !== "admin"} onChange={(event) => setFromStore(event.target.value as Store)}><option>Viterbo</option><option>Gran Sasso</option></select></label><ProductSearch compact products={data.products} store={fromStore} onAdd={add} /><div className="cart-list transfer-lines">{items.map((item) => { const product = data.products.find((row) => row.id === item.productId); const available = product ? (fromStore === "Viterbo" ? product.viterboQty - product.viterboReserved : product.granSassoQty - product.granSassoReserved) : 0; const danger = item.quantity > available; return <div className={`cart-row ${danger ? "insufficient-row" : ""}`} key={item.key}><div className="cart-desc"><strong>{item.description}</strong><small>Disponibili: {available}</small></div><ClearableInput compact type="number" min="1" value={item.quantity} onChange={(value) => setItems((current) => current.map((row) => row.key === item.key ? { ...row, quantity: Number(value) || 0 } : row))} /><span className={danger ? "negative" : "stock-ok"}>{danger ? "INSUFFICIENTE" : "OK"}</span><button className="icon-button" onClick={() => setItems((current) => current.filter((row) => row.key !== item.key))}>×</button></div>; })}</div></div><aside className="panel"><p className="eyebrow">DATI BOLLA DI TRASPORTO</p><h2>Da {fromStore} a {fromStore === "Viterbo" ? "Gran Sasso" : "Viterbo"}</h2><div className="stack"><ClearableInput label="Mittente" value={sender} onChange={setSender} required /><ClearableInput label="Ricevente" value={receiver} onChange={setReceiver} required /><ClearableInput label="Vettore" value={carrier} onChange={setCarrier} required /><ClearableInput label="Causale" value={reason} onChange={setReason} /><button className="primary" disabled={!items.length || insufficients.length > 0} onClick={submit}>Conferma trasferimento</button>{last && <a className="secondary center" href={`/api/pdf?type=ddt&id=${last.id}`}>Scarica DDT {last.code}</a>}</div></aside></div><div className="panel"><div className="panel-title"><h2>Ultimi trasferimenti</h2></div><div className="table-wrap"><table><thead><tr><th>Codice</th><th>Data</th><th>Tratta</th><th>Vettore</th><th>Quantità</th><th>DDT</th></tr></thead><tbody>{data.transfers.map((transfer) => <tr key={transfer.id}><td>{transfer.code}</td><td>{dateTime(transfer.createdAt)}</td><td>{transfer.fromStore} → {transfer.toStore}</td><td>{transfer.carrier}</td><td>{transfer.totalQuantity}</td><td><a href={`/api/pdf?type=ddt&id=${transfer.id}`}>PDF</a></td></tr>)}</tbody></table></div></div></section>;
}

function QuickLoad({ data, reload }: { data: Bootstrap; reload: () => Promise<void> }) {
  type VariantDraft = { key: string; sku: string; color: string; size: string; eans: string; viterboQty: string; granSassoQty: string; photo: File | null; photoPreview: string };
  const emptyVariant = (): VariantDraft => ({ key: keyId(), sku: "", color: "", size: "", eans: "", viterboQty: "0", granSassoQty: "0", photo: null, photoPreview: "" });
  const [ean, setEan] = useState("");
  const [store, setStore] = useState<Store>(data.user.store ?? "Viterbo");
  const [quantity, setQuantity] = useState("1");
  const [message, setMessage] = useState("");
  const [error, setError] = useState("");
  const [saving, setSaving] = useState(false);
  const [form, setForm] = useState({ name: "", brand: "", category: "", price: "" });
  const [variants, setVariants] = useState<VariantDraft[]>([emptyVariant()]);
  async function load() { setError(""); try { const result = await post("quickLoad", { ean, store, quantity }); setMessage(`${result.product.name}: +${result.quantity} a ${result.store}`); setEan(""); await reload(); } catch (reason) { setError(reason instanceof Error ? reason.message : "Errore."); } }
  async function create(event: React.FormEvent) {
    event.preventDefault(); setError(""); setMessage(""); setSaving(true);
    try {
      const createdName = form.name;
      const body = new FormData();
      body.append("payload", JSON.stringify({ ...form, variants: variants.map(({ sku, color, size, eans, viterboQty, granSassoQty }) => ({ sku, color, size, eans: eans.split(",").map((value) => value.trim()).filter(Boolean), viterboQty, granSassoQty })) }));
      variants.forEach((variant, index) => { if (variant.photo) body.append(`photo-${index}`, variant.photo); });
      const result = await readJson(await fetch("/api/products", { method: "POST", body }));
      setForm({ name: "", brand: "", category: "", price: "" }); setVariants([emptyVariant()]);
      setMessage(`${createdName}: prodotto creato con ${result.variantCount} ${result.variantCount === 1 ? "variante" : "varianti"} e ${result.photos} foto colore.`); await reload();
    } catch (reason) { setError(reason instanceof Error ? reason.message : "Errore."); }
    finally { setSaving(false); }
  }
  const change = (name: keyof typeof form) => (value: string) => setForm((current) => ({ ...current, [name]: value }));
  function changeVariant(key: string, name: keyof Omit<VariantDraft, "key" | "photo" | "photoPreview">, value: string) { setVariants((current) => current.map((variant) => variant.key === key ? { ...variant, [name]: value } : variant)); }
  function choosePhoto(key: string, file: File | null) {
    if (!file) { setVariants((current) => current.map((variant) => variant.key === key ? { ...variant, photo: null, photoPreview: "" } : variant)); return; }
    const reader = new FileReader();
    reader.onload = () => setVariants((current) => current.map((variant) => variant.key === key ? { ...variant, photo: file, photoPreview: String(reader.result ?? "") } : variant));
    reader.readAsDataURL(file);
  }
  return <section className="screen"><div className="screen-head"><div><p className="eyebrow">GESTIONE MAGAZZINO</p><h1>Carico prodotti</h1></div></div>{message && <div className="alert success">{message}</div>}{error && <div className="alert danger visual-alert">⚠ {error}</div>}<div className="product-load-grid"><div className="panel"><p className="eyebrow">CARICO RAPIDO</p><h2>Scansione EAN</h2><div className="stack"><ClearableInput label="EAN riconosciuto" value={ean} onChange={setEan} onKeyDown={(event) => { if (event.key === "Enter") { event.preventDefault(); void load(); } }} autoFocus /><label className="field"><span>Negozio</span><select value={store} disabled={data.user.role !== "admin"} onChange={(event) => setStore(event.target.value as Store)}><option>Viterbo</option><option>Gran Sasso</option></select></label><ClearableInput label="Quantità" type="number" min="1" value={quantity} onChange={setQuantity} /><button className="primary" onClick={load}>Carica giacenza</button></div></div><div className="panel"><div className="panel-title"><div><p className="eyebrow">NUOVO PRODOTTO</p><h2>Un prodotto, tutte le varianti</h2><p className="muted product-group-note">Marca, nome e categoria vengono salvati una sola volta. Colori, taglie, SKU, EAN e giacenze restano separati nelle varianti.</p></div><span className="count-pill">{variants.length} varianti</span></div><form className="stack" onSubmit={create}><div className="form-grid product-base-fields"><ClearableInput label="Nome prodotto" value={form.name} onChange={change("name")} required /><ClearableInput label="Marca" value={form.brand} onChange={change("brand")} required /><ClearableInput label="Categoria" value={form.category} onChange={change("category")} required /><ClearableInput label="Prezzo di vendita" type="number" min="0" step="0.01" value={form.price} onChange={change("price")} required /></div><div className="variant-builder-head"><div><p className="eyebrow">VARIANTI DEL PRODOTTO</p><p className="muted">Aggiungi qui colori e taglie senza duplicare il prodotto. Ogni variante mantiene i propri EAN e la propria giacenza.</p></div><button type="button" className="secondary" onClick={() => setVariants((current) => [...current, emptyVariant()])}>＋ Aggiungi variante</button></div><div className="variant-list">{variants.map((variant, index) => <article className="variant-card" key={variant.key}><div className="variant-card-head"><strong>Variante {index + 1}</strong>{variants.length > 1 && <button type="button" className="text-button negative" onClick={() => setVariants((current) => current.filter((row) => row.key !== variant.key))}>Rimuovi</button>}</div><div className="variant-fields"><ClearableInput label="Colore" value={variant.color} onChange={(value) => changeVariant(variant.key, "color", value)} required /><ClearableInput label="Taglia" value={variant.size} onChange={(value) => changeVariant(variant.key, "size", value)} required /><ClearableInput label="SKU variante" value={variant.sku} onChange={(value) => changeVariant(variant.key, "sku", value)} required /><ClearableInput className="variant-eans" label="EAN separati da virgola" value={variant.eans} onChange={(value) => changeVariant(variant.key, "eans", value)} required />{(data.user.role === "admin" || data.user.store === "Viterbo") && <ClearableInput label="Giacenza Viterbo" type="number" min="0" value={variant.viterboQty} onChange={(value) => changeVariant(variant.key, "viterboQty", value)} />}{(data.user.role === "admin" || data.user.store === "Gran Sasso") && <ClearableInput label="Giacenza Gran Sasso" type="number" min="0" value={variant.granSassoQty} onChange={(value) => changeVariant(variant.key, "granSassoQty", value)} />}<label className="field variant-photo-field"><span>Foto della variante colore</span><input type="file" accept="image/jpeg,image/png,image/webp" onChange={(event) => choosePhoto(variant.key, event.target.files?.[0] ?? null)} /></label>{variant.photoPreview && <div className="variant-photo-preview"><img src={variant.photoPreview} alt={`Anteprima ${variant.color || `variante ${index + 1}`}`} /><button type="button" className="icon-button" aria-label="Rimuovi foto" onClick={() => choosePhoto(variant.key, null)}>×</button></div>}</div></article>)}</div><button className="primary full-button" disabled={saving}>{saving ? "Caricamento…" : `Salva un prodotto con ${variants.length} ${variants.length === 1 ? "variante" : "varianti"}`}</button></form></div></div></section>;
}

function GiftSummary({ data }: { data: Bootstrap }) {
  const [query, setQuery] = useState(""); const visible = data.gifts.filter((gift) => `${gift.code} ${gift.beneficiary} ${gift.store}`.toLowerCase().includes(query.toLowerCase()));
  return <section className="screen"><div className="screen-head"><div><p className="eyebrow">AMMINISTRAZIONE</p><h1>Riepilogo buoni regalo</h1></div></div><div className="metric-grid"><Metric label="Valore emesso" value={money(data.gifts.reduce((sum, gift) => sum + gift.initialValue, 0))} /><Metric label="Valore utilizzato" value={money(data.gifts.reduce((sum, gift) => sum + gift.initialValue - gift.balance, 0))} /><Metric label="Saldo residuo" value={money(data.gifts.reduce((sum, gift) => sum + gift.balance, 0))} /></div><div className="panel"><ClearableInput label="Ricerca codice o intestatario" value={query} onChange={setQuery} /><div className="table-wrap"><table><thead><tr><th>Codice</th><th>Intestatario</th><th>Sede</th><th>Emesso</th><th>Residuo</th><th>Scadenza</th><th>Stato</th><th>PDF</th></tr></thead><tbody>{visible.map((gift) => <tr key={gift.id}><td>{gift.code}</td><td>{gift.beneficiary}</td><td>{gift.store}</td><td>{money(gift.initialValue)}</td><td><b>{money(gift.balance)}</b></td><td>{new Date(gift.expiresAt).toLocaleDateString("it-IT")}</td><td><span className={`status ${gift.status}`}>{gift.status === "reversed" ? "stornato" : gift.status}</span></td><td><a href={`/api/pdf?type=gift&id=${gift.id}`}>Scarica</a></td></tr>)}</tbody></table></div></div></section>;
}

function ReservationSummary({ data }: { data: Bootstrap }) {
  const [query, setQuery] = useState("");
  const visible = data.reservations.filter((reservation) => (data.user.role === "admin" || reservation.store === data.user.store) && `${reservation.code} ${reservation.description} ${reservation.itemDescriptions} ${reservation.customerName}`.toLowerCase().includes(query.toLowerCase()));
  return <section className="screen"><div className="screen-head"><div><p className="eyebrow">ACCONTI E RITIRI</p><h1>Prenotazioni e risuolature</h1></div></div><div className="panel"><ClearableInput label="Ricerca codice, prodotto o cliente" value={query} onChange={setQuery} /><div className="table-wrap"><table><thead><tr><th>Codice</th><th>Data</th><th>Sede</th><th>Descrizione</th><th>Articoli</th><th>Cliente</th><th>Acconto</th><th>Saldo</th><th>Stato</th><th>PDF EAN</th></tr></thead><tbody>{visible.map((reservation) => <tr key={reservation.id}><td>{reservation.code}</td><td>{dateTime(reservation.createdAt)}</td><td>{reservation.store}</td><td>{reservation.kind === "repair" ? <><strong>Risuolatura</strong><small>{reservation.itemDescriptions || reservation.description}</small></> : reservation.description}</td><td>{reservation.itemCount || 1}</td><td>{reservation.customerName || "Non associato"}</td><td>{money(reservation.depositAmount)}</td><td><b>{money(reservation.balanceDue)}</b></td><td><span className={`status ${reservation.status === "open" ? "active" : "used"}`}>{reservation.status}</span></td><td><a href={`/api/pdf?type=reservation&id=${reservation.id}`}>Scarica</a></td></tr>)}</tbody></table></div></div></section>;
}

type TransferAdminItem = { productId: number; quantity: number; name: string; brand: string; color: string; size: string };
type AdminEdit =
  | { kind: "product"; record: Product }
  | { kind: "customer"; record: Customer }
  | { kind: "gift"; record: Gift }
  | { kind: "reservation"; record: Reservation }
  | { kind: "transfer"; record: Transfer; items: TransferAdminItem[] };

function ProductAdminForm({ product, reload, close }: { product: Product; reload: () => Promise<void>; close: () => void }) {
  const [form, setForm] = useState({ name: product.name, brand: product.brand, category: product.category, sku: product.sku, color: product.color, size: product.size, price: String(product.price), eans: product.eans, viterboQty: String(product.viterboQty), granSassoQty: String(product.granSassoQty) });
  const [error, setError] = useState("");
  const set = (name: keyof typeof form) => (value: string) => setForm((current) => ({ ...current, [name]: value }));
  async function save(event: React.FormEvent) { event.preventDefault(); setError(""); try { await post("updateProduct", { id: product.id, ...form, eans: form.eans.split(",").map((value) => value.trim()).filter(Boolean) }); await reload(); close(); } catch (reason) { setError(reason instanceof Error ? reason.message : "Errore."); } }
  return <form className="stack" onSubmit={save}><div className="form-grid"><ClearableInput label="Nome prodotto" value={form.name} onChange={set("name")} required /><ClearableInput label="Marca" value={form.brand} onChange={set("brand")} required /><ClearableInput label="Categoria" value={form.category} onChange={set("category")} required /><ClearableInput label="Prezzo vendita" type="number" min="0.01" step="0.01" value={form.price} onChange={set("price")} required /><ClearableInput label="SKU variante" value={form.sku} onChange={set("sku")} required /><ClearableInput label="Colore" value={form.color} onChange={set("color")} required /><ClearableInput label="Taglia" value={form.size} onChange={set("size")} required /><ClearableInput className="full" label="EAN separati da virgola" value={form.eans} onChange={set("eans")} required /><ClearableInput label={`Giacenza Viterbo · ${product.viterboReserved} prenotati`} type="number" min={product.viterboReserved} value={form.viterboQty} onChange={set("viterboQty")} /><ClearableInput label={`Giacenza Gran Sasso · ${product.granSassoReserved} prenotati`} type="number" min={product.granSassoReserved} value={form.granSassoQty} onChange={set("granSassoQty")} />{error && <div className="alert danger full">{error}</div>}<div className="form-actions full"><button type="button" className="secondary" onClick={close}>Annulla</button><button className="primary">Salva modifiche</button></div></div></form>;
}

function GiftAdminForm({ gift, reload, close }: { gift: Gift; reload: () => Promise<void>; close: () => void }) {
  const [beneficiary, setBeneficiary] = useState(gift.beneficiary); const [initialValue, setInitialValue] = useState(String(gift.initialValue)); const [balance, setBalance] = useState(String(gift.balance)); const [expiresAt, setExpiresAt] = useState(gift.expiresAt.slice(0, 10)); const [status, setStatus] = useState(gift.status); const [error, setError] = useState("");
  async function save(event: React.FormEvent) { event.preventDefault(); setError(""); try { await post("updateGift", { id: gift.id, beneficiary, initialValue, balance, expiresAt, status }); await reload(); close(); } catch (reason) { setError(reason instanceof Error ? reason.message : "Errore."); } }
  return <form className="stack" onSubmit={save}><ClearableInput label="Intestatario" value={beneficiary} onChange={setBeneficiary} required /><div className="form-grid"><ClearableInput label="Valore emesso" type="number" min="0.01" step="0.01" value={initialValue} onChange={setInitialValue} required /><ClearableInput label="Saldo residuo" type="number" min="0" step="0.01" value={balance} onChange={setBalance} required /><ClearableInput label="Scadenza" type="date" value={expiresAt} onChange={setExpiresAt} required /><label className="field"><span>Stato</span><select value={status} onChange={(event) => setStatus(event.target.value)}><option value="active">Attivo</option><option value="used">Utilizzato</option><option value="expired">Scaduto</option><option value="reversed">Stornato</option></select></label></div>{error && <div className="alert danger">{error}</div>}<div className="form-actions"><button type="button" className="secondary" onClick={close}>Annulla</button><button className="primary">Salva modifiche</button></div></form>;
}

function ReservationAdminForm({ reservation, reload, close }: { reservation: Reservation; reload: () => Promise<void>; close: () => void }) {
  const [description, setDescription] = useState(reservation.description); const [totalPrice, setTotalPrice] = useState(String(reservation.totalPrice)); const [depositAmount, setDepositAmount] = useState(String(reservation.depositAmount)); const [status, setStatus] = useState(reservation.status); const [error, setError] = useState("");
  async function save(event: React.FormEvent) { event.preventDefault(); setError(""); try { await post("updateReservation", { id: reservation.id, description, totalPrice, depositAmount, status }); await reload(); close(); } catch (reason) { setError(reason instanceof Error ? reason.message : "Errore."); } }
  return <form className="stack" onSubmit={save}><ClearableInput label="Descrizione" value={description} onChange={setDescription} required /><div className="form-grid"><ClearableInput label="Totale concordato" type="number" min="0.01" step="0.01" value={totalPrice} onChange={setTotalPrice} required /><ClearableInput label="Acconto versato" type="number" min="0" step="0.01" value={depositAmount} onChange={setDepositAmount} required /><label className="field full"><span>Stato</span><select value={status} disabled={reservation.status === "completed"} onChange={(event) => setStatus(event.target.value)}><option value="open">Aperta</option><option value="cancelled">Annullata</option>{reservation.status === "completed" && <option value="completed">Completata</option>}</select></label></div>{error && <div className="alert danger">{error}</div>}<div className="form-actions"><button type="button" className="secondary" onClick={close}>Annulla</button><button className="primary">Salva modifiche</button></div></form>;
}

function TransferAdminForm({ transfer, items, reload, close }: { transfer: Transfer; items: TransferAdminItem[]; reload: () => Promise<void>; close: () => void }) {
  const [sender, setSender] = useState(transfer.sender); const [receiver, setReceiver] = useState(transfer.receiver); const [carrier, setCarrier] = useState(transfer.carrier); const [transportReason, setTransportReason] = useState(transfer.transportReason); const [lines, setLines] = useState(items); const [error, setError] = useState("");
  async function save(event: React.FormEvent) { event.preventDefault(); setError(""); try { await post("updateTransfer", { id: transfer.id, sender, receiver, carrier, transportReason, items: lines.map(({ productId, quantity }) => ({ productId, quantity })) }); await reload(); close(); } catch (reason) { setError(reason instanceof Error ? reason.message : "Errore."); } }
  return <form className="stack" onSubmit={save}><div className="form-grid"><ClearableInput label="Mittente" value={sender} onChange={setSender} required /><ClearableInput label="Ricevente" value={receiver} onChange={setReceiver} required /><ClearableInput label="Vettore" value={carrier} onChange={setCarrier} required /><ClearableInput label="Causale" value={transportReason} onChange={setTransportReason} required /></div><div className="cart-list transfer-lines">{lines.map((item) => <div className="cart-row" key={item.productId}><div className="cart-desc"><strong>{item.brand ? `${item.brand} · ` : ""}{item.name}</strong><small>{item.color} · {item.size}</small></div><ClearableInput compact label="Quantità" type="number" min="1" value={item.quantity} onChange={(value) => setLines((current) => current.map((line) => line.productId === item.productId ? { ...line, quantity: Math.max(1, Number(value) || 1) } : line))} /></div>)}</div>{error && <div className="alert danger">{error}</div>}<div className="form-actions"><button type="button" className="secondary" onClick={close}>Annulla</button><button className="primary">Salva modifiche DDT</button></div></form>;
}

function AdminDataManagement({ data, reload }: { data: Bootstrap; reload: () => Promise<void> }) {
  const [section, setSection] = useState<"products" | "customers" | "gifts" | "reservations" | "transfers">("products"); const [query, setQuery] = useState(""); const [editing, setEditing] = useState<AdminEdit | null>(null); const [message, setMessage] = useState(""); const [error, setError] = useState("");
  const normalized = query.trim().toLocaleLowerCase("it");
  async function editTransfer(transfer: Transfer) { setError(""); try { const detail = await readJson(await firebaseAuthenticatedFetch(`/api/data?view=transfer&id=${transfer.id}`, { cache: "no-store" })); setEditing({ kind: "transfer", record: transfer, items: detail.items as TransferAdminItem[] }); } catch (reason) { setError(reason instanceof Error ? reason.message : "Errore."); } }
  async function remove(action: string, id: number, label: string) { if (!confirm(`Cancellare ${label}? L'operazione aggiornerà automaticamente i dati collegati quando necessario.`)) return; setError(""); setMessage(""); try { await post(action, { id }); setEditing(null); setMessage(`${label} rimosso correttamente.`); await reload(); } catch (reason) { setError(reason instanceof Error ? reason.message : "Errore."); } }
  const products = data.products.filter((item) => !normalized || searchableProduct(item).includes(normalized));
  const customers = data.customers.filter((item) => !normalized || `${customerLabel(item)} ${item.vatNumber} ${item.taxCode} ${item.city}`.toLocaleLowerCase("it").includes(normalized));
  const gifts = data.gifts.filter((item) => !normalized || `${item.code} ${item.beneficiary} ${item.store}`.toLocaleLowerCase("it").includes(normalized));
  const reservations = data.reservations.filter((item) => !normalized || `${item.code} ${item.description} ${item.customerName}`.toLocaleLowerCase("it").includes(normalized));
  const transfers = data.transfers.filter((item) => !normalized || `${item.code} ${item.fromStore} ${item.toStore} ${item.carrier}`.toLocaleLowerCase("it").includes(normalized));
  return <section className="screen"><div className="screen-head"><div><p className="eyebrow">SOLO AMMINISTRAZIONE</p><h1>Modifica e cancellazione dati</h1><p className="muted inventory-intro">Gestisci prodotti, clienti, buoni, prenotazioni e trasferimenti già inseriti senza alterare lo storico contabile.</p></div></div>{message && <div className="alert success">{message}</div>}{error && <div className="alert danger visual-alert">⚠ {error}</div>}<div className="panel"><div className="customer-type-tabs section-tabs">{[["products","Prodotti",data.products.length],["customers","Clienti",data.customers.length],["gifts","Buoni",data.gifts.length],["reservations","Prenotazioni",data.reservations.length],["transfers","Trasferimenti",data.transfers.length]].map(([id,label,count]) => <button key={String(id)} className={section === id ? "active" : ""} onClick={() => { setSection(id as typeof section); setQuery(""); }}>{label} <b>{count}</b></button>)}</div><ClearableInput label="Ricerca" value={query} onChange={setQuery} placeholder="Cerca nel riepilogo selezionato…" /></div><div className="panel"><div className="table-wrap">{section === "products" && <table><thead><tr><th>Prodotto</th><th>Variante</th><th>SKU / EAN</th><th>Prezzo</th><th>Giacenze</th><th>Azioni</th></tr></thead><tbody>{products.map((item) => <tr key={item.id}><td><strong>{item.brand} · {item.name}</strong><small>{item.category}</small></td><td>{item.color} · {item.size}</td><td>{item.sku}<small>{item.eans.split(",").join(" · ")}</small></td><td>{money(item.price)}</td><td>VT {item.viterboQty} · GS {item.granSassoQty}</td><td><div className="table-actions"><button className="secondary small" onClick={() => setEditing({ kind: "product", record: item })}>Modifica</button><button className="text-button negative" onClick={() => void remove("deleteProduct", item.id, `${item.name} ${item.color} ${item.size}`)}>Rimuovi</button></div></td></tr>)}</tbody></table>}{section === "customers" && <table><thead><tr><th>Nominativo</th><th>Tipo</th><th>Recapito</th><th>Sede</th><th>Azioni</th></tr></thead><tbody>{customers.map((item) => <tr key={item.id}><td><strong>{customerLabel(item)}</strong><small>{item.vatNumber || item.taxCode}</small></td><td>{item.customerType === "company" ? "Azienda" : "Privato"}</td><td>{item.email || item.phone || "—"}</td><td>{item.scope}</td><td><div className="table-actions"><button className="secondary small" onClick={() => setEditing({ kind: "customer", record: item })}>Modifica</button><button className="text-button negative" onClick={() => void remove("deleteCustomer", item.id, customerLabel(item))}>Rimuovi</button></div></td></tr>)}</tbody></table>}{section === "gifts" && <table><thead><tr><th>Codice</th><th>Intestatario</th><th>Emesso</th><th>Residuo</th><th>Stato</th><th>Azioni</th></tr></thead><tbody>{gifts.map((item) => <tr key={item.id}><td>{item.code}</td><td>{item.beneficiary}</td><td>{money(item.initialValue)}</td><td>{money(item.balance)}</td><td>{item.status}</td><td><div className="table-actions"><button className="secondary small" onClick={() => setEditing({ kind: "gift", record: item })}>Modifica</button><button className="text-button negative" onClick={() => void remove("deleteGift", item.id, `il buono ${item.code}`)}>Rimuovi</button></div></td></tr>)}</tbody></table>}{section === "reservations" && <table><thead><tr><th>Codice</th><th>Descrizione</th><th>Cliente</th><th>Totale</th><th>Stato</th><th>Azioni</th></tr></thead><tbody>{reservations.map((item) => <tr key={item.id}><td>{item.code}</td><td>{item.description}</td><td>{item.customerName || "Non associato"}</td><td>{money(item.totalPrice)}</td><td>{item.status}</td><td><div className="table-actions"><button className="secondary small" onClick={() => setEditing({ kind: "reservation", record: item })}>Modifica</button><button className="text-button negative" onClick={() => void remove("deleteReservation", item.id, `la prenotazione ${item.code}`)}>Rimuovi</button></div></td></tr>)}</tbody></table>}{section === "transfers" && <table><thead><tr><th>Codice</th><th>Tratta</th><th>Vettore</th><th>Quantità</th><th>Data</th><th>Azioni</th></tr></thead><tbody>{transfers.map((item) => <tr key={item.id}><td>{item.code}</td><td>{item.fromStore} → {item.toStore}</td><td>{item.carrier}</td><td>{item.totalQuantity}</td><td>{dateTime(item.createdAt)}</td><td><div className="table-actions"><button className="secondary small" onClick={() => void editTransfer(item)}>Modifica</button><button className="text-button negative" onClick={() => void remove("deleteTransfer", item.id, `il trasferimento ${item.code}`)}>Rimuovi</button></div></td></tr>)}</tbody></table>}</div></div>{editing && <Modal title={`Modifica ${editing.kind === "product" ? "prodotto" : editing.kind === "customer" ? "cliente" : editing.kind === "gift" ? "buono" : editing.kind === "reservation" ? "prenotazione" : "trasferimento"}`} onClose={() => setEditing(null)}>{editing.kind === "product" && <ProductAdminForm product={editing.record} reload={reload} close={() => setEditing(null)} />}{editing.kind === "customer" && <CustomerForm customer={editing.record} store={editing.record.createdStore} onSaved={reload} onClose={() => setEditing(null)} />}{editing.kind === "gift" && <GiftAdminForm gift={editing.record} reload={reload} close={() => setEditing(null)} />}{editing.kind === "reservation" && <ReservationAdminForm reservation={editing.record} reload={reload} close={() => setEditing(null)} />}{editing.kind === "transfer" && <TransferAdminForm transfer={editing.record} items={editing.items} reload={reload} close={() => setEditing(null)} />}</Modal>}</section>;
}

function Metric({ label, value, note }: { label: string; value: string; note?: string }) { return <article className="metric"><small>{label}</small><strong>{value}</strong>{note && <span>{note}</span>}</article>; }

function CashReports({ data }: { data: Bootstrap }) {
  const [mode, setMode] = useState("monthly"); const [store, setStore] = useState<"Tutti" | Store>("Tutti");
  const groups = useMemo(() => { const map = new Map<string, { total: number; sales: number; returns: number; cash: number; pos: number; bank: number; gift: number; count: number }>(); for (const sale of data.sales) { if (store !== "Tutti" && sale.store !== store) continue; const date = new Date(sale.createdAt); const key = mode === "daily" ? date.toLocaleDateString("it-IT") : date.toLocaleDateString("it-IT", { month: "long", year: "numeric" }); const current = map.get(key) ?? { total: 0, sales: 0, returns: 0, cash: 0, pos: 0, bank: 0, gift: 0, count: 0 }; current.total += sale.total; current.cash += sale.cashAmount; current.pos += sale.cardAmount; current.bank += sale.bankAmount; current.gift += sale.giftAmount; current.count += 1; if (sale.total < 0) current.returns += sale.total; else current.sales += sale.total; map.set(key, current); } return [...map.entries()].sort((left, right) => right[0].localeCompare(left[0], "it")); }, [data.sales, mode, store]);
  return <section className="screen"><div className="screen-head"><div><p className="eyebrow">CORRISPETTIVI</p><h1>Riepilogo incassi</h1><p className="muted inventory-intro">Cash, POS e bonifici sono separati sia nel riepilogo giornaliero sia in quello mensile.</p></div><div className="head-controls"><label className="field inline"><span>Periodo</span><select value={mode} onChange={(event) => setMode(event.target.value)}><option value="monthly">Mensili</option><option value="daily">Giornalieri</option></select></label><label className="field inline"><span>Negozio</span><select value={store} onChange={(event) => setStore(event.target.value as "Tutti" | Store)}><option>Tutti</option><option>Viterbo</option><option>Gran Sasso</option></select></label></div></div><div className="panel"><div className="table-wrap"><table><thead><tr><th>Periodo</th><th>Cash</th><th>POS</th><th>Bonifici</th><th>Buoni</th><th>Vendite</th><th>Resi</th><th>Netto</th><th>Movimenti</th></tr></thead><tbody>{groups.map(([period, row]) => <tr key={period}><td><strong>{period}</strong></td><td><b>{money(row.cash)}</b></td><td><b>{money(row.pos)}</b></td><td><b>{money(row.bank)}</b></td><td>{money(row.gift)}</td><td>{money(row.sales)}</td><td className="negative">{money(row.returns)}</td><td><b>{money(row.total)}</b></td><td>{row.count}</td></tr>)}</tbody></table></div></div></section>;
}

function Register({ data }: { data: Bootstrap }) {
  const [query, setQuery] = useState(""); const visible = data.sales.filter((sale) => `${sale.receiptNo} ${sale.customerName} ${sale.store}`.toLowerCase().includes(query.toLowerCase()));
  const ownStore = data.user.store;
  return <section className="screen"><div className="screen-head"><div><p className="eyebrow">RICERCA PER NOMINATIVO</p><h1>Vendite effettuate{ownStore ? ` · ${ownStore}` : ""}</h1><p className="muted inventory-intro">{ownStore ? `Sono visibili esclusivamente le vendite registrate dal negozio ${ownStore}.` : "L’amministratore può consultare le vendite di entrambi i negozi."}</p></div></div><div className="metric-grid">{data.user.role === "admin" ? <><Metric label="Netto Viterbo" value={money(data.sales.filter((sale) => sale.store === "Viterbo").reduce((sum, sale) => sum + sale.total, 0))} /><Metric label="Netto Gran Sasso" value={money(data.sales.filter((sale) => sale.store === "Gran Sasso").reduce((sum, sale) => sum + sale.total, 0))} /></> : <Metric label={`Netto ${ownStore}`} value={money(data.sales.reduce((sum, sale) => sum + sale.total, 0))} />}<Metric label="Totale visibile" value={money(data.sales.reduce((sum, sale) => sum + sale.total, 0))} note={`${data.sales.length} movimenti`} /></div><div className="panel"><ClearableInput label="Ricerca per nominativo cliente o numero scontrino" value={query} onChange={setQuery} placeholder="Scrivi nome e cognome…" /><div className="table-wrap"><table><thead><tr><th>Data</th><th>Sede</th><th>Scontrino</th><th>Cliente</th><th>Contanti</th><th>Carta</th><th>Bonifico</th><th>Buono</th><th>Totale</th><th>Stampa</th></tr></thead><tbody>{visible.map((sale) => <tr key={sale.id} className={sale.total < 0 ? "return-row" : ""}><td>{dateTime(sale.createdAt)}</td><td>{sale.store}</td><td>{sale.receiptNo}</td><td>{sale.customerName}</td><td>{money(sale.cashAmount)}</td><td>{money(sale.cardAmount)}</td><td>{money(sale.bankAmount)}</td><td>{money(sale.giftAmount)}</td><td className={sale.total < 0 ? "negative" : ""}><b>{money(sale.total)}</b></td><td><a href={`/api/pdf?type=receipt&id=${sale.id}`}>PDF</a></td></tr>)}</tbody></table></div></div></section>;
}

function Documents({ data, reload }: { data: Bootstrap; reload: () => Promise<void> }) {
  type DocumentLine = { key: string; productId: number | null; description: string; quantity: number; unitPrice: number; taxRate: number };
  const [type, setType] = useState("quote"); const [origin, setOrigin] = useState("Ordine"); const [paymentMethod, setPaymentMethod] = useState("cash"); const [items, setItems] = useState<DocumentLine[]>([]); const [description, setDescription] = useState(""); const [quantity, setQuantity] = useState("1"); const [price, setPrice] = useState(""); const [taxRate, setTaxRate] = useState("22"); const [customerId, setCustomerId] = useState(""); const [recipient, setRecipient] = useState({ name: "", vatNumber: "", pec: "", sdiCode: "", address: "", postalCode: "", city: "", province: "" }); const [last, setLast] = useState<{ id: number; number: string } | null>(null); const [error, setError] = useState("");
  const companyCustomers = data.customers.filter((customer) => customer.customerType === "company");
  const netTotal = items.reduce((sum, item) => sum + item.quantity * item.unitPrice, 0);
  const taxTotal = items.reduce((sum, item) => sum + item.quantity * item.unitPrice * item.taxRate / 100, 0);
  function selectCustomer(value: string) { setCustomerId(value); const customer = data.customers.find((item) => item.id === Number(value)); if (customer) setRecipient({ name: customerLabel(customer), vatNumber: customer.vatNumber || customer.taxCode || "", pec: customer.pec || "", sdiCode: customer.sdiCode || "", address: customer.address || "", postalCode: customer.postalCode || "", city: customer.city || "", province: customer.province || "" }); }
  function addProduct(product: Product) { if (items.some((item) => item.productId === product.id)) return; setItems((current) => [...current, { key: keyId(), productId: product.id, description: `${product.brand ? `${product.brand} · ` : ""}${product.name} · ${product.color} ${product.size}`, quantity: 1, unitPrice: product.price, taxRate: 22 }]); }
  function addLine() { if (!description || Number(quantity) <= 0) return; setItems((current) => [...current, { key: keyId(), productId: null, description, quantity: Number(quantity), unitPrice: Number(price) || 0, taxRate: Number(taxRate) || 0 }]); setDescription(""); setQuantity("1"); setPrice(""); }
  function updateLine(key: string, change: Partial<DocumentLine>) { setItems((current) => current.map((item) => item.key === key ? { ...item, ...change } : item)); }
  async function create() { setError(""); try { const result = await post("createDocument", { documentType: type, customerId: customerId || null, recipient: recipient.name, recipientVatNumber: recipient.vatNumber, recipientPec: recipient.pec, recipientSdiCode: recipient.sdiCode, recipientAddress: recipient.address, recipientPostalCode: recipient.postalCode, recipientCity: recipient.city, recipientProvince: recipient.province, origin, paymentMethod, items }); setLast({ id: result.documentId, number: result.number }); setItems([]); await reload(); } catch (reason) { setError(reason instanceof Error ? reason.message : "Errore."); } }
  const setRecipientField = (name: keyof typeof recipient) => (value: string) => setRecipient((current) => ({ ...current, [name]: value }));
  return <section className="screen"><div className="screen-head"><div><p className="eyebrow">DOCUMENTI MULTIPRODOTTO CON IVA</p><h1>Preventivi e fatture</h1><p className="muted inventory-intro">Tutti i prezzi inseriti in questa sezione sono imponibili IVA esclusa.</p></div></div>{error && <div className="alert danger">{error}</div>}<div className="documents-layout"><div className="stack"><div className="panel"><div className="panel-title"><div><p className="eyebrow">DATI DOCUMENTO</p><h2>Destinatario</h2></div></div><div className="form-grid"><label className="field"><span>Tipo documento</span><select value={type} onChange={(event) => setType(event.target.value)}><option value="quote">Preventivo</option><option value="invoice">Fattura</option></select></label><label className="field"><span>Origine merce</span><select value={origin} onChange={(event) => setOrigin(event.target.value)}><option>Ordine</option><option>Viterbo</option><option>Gran Sasso</option></select></label>{type === "invoice" && <label className="field"><span>Pagamento fattura</span><select value={paymentMethod} onChange={(event) => setPaymentMethod(event.target.value)}><option value="cash">Contanti</option><option value="bank">Bonifico bancario</option><option value="card">Carta</option></select></label>}<label className="field full"><span>Azienda dall&apos;anagrafica</span><select value={customerId} onChange={(event) => selectCustomer(event.target.value)}><option value="">Compilazione manuale</option>{companyCustomers.map((customer) => <option key={customer.id} value={customer.id}>{customer.companyName} · P.IVA {customer.vatNumber}</option>)}</select></label><ClearableInput className="full" label="Ragione sociale / destinatario" value={recipient.name} onChange={setRecipientField("name")} required /><ClearableInput label="Partita IVA" value={recipient.vatNumber} onChange={setRecipientField("vatNumber")} /><ClearableInput label="PEC" value={recipient.pec} onChange={setRecipientField("pec")} /><ClearableInput label="Codice SDI" value={recipient.sdiCode} onChange={setRecipientField("sdiCode")} /><ClearableInput className="full" label="Indirizzo" value={recipient.address} onChange={setRecipientField("address")} /><ClearableInput label="CAP" value={recipient.postalCode} onChange={setRecipientField("postalCode")} /><ClearableInput label="Comune" value={recipient.city} onChange={setRecipientField("city")} /><ClearableInput label="Provincia" value={recipient.province} onChange={setRecipientField("province")} maxLength={2} /></div></div><div className="panel"><div className="panel-title"><div><p className="eyebrow">ARTICOLI</p><h2>Aggiungi più prodotti</h2></div><span className="count-pill">{items.length} righe</span></div><ProductSearch compact products={data.products} store={origin === "Gran Sasso" ? "Gran Sasso" : "Viterbo"} onAdd={addProduct} /><div className="manual-document-line"><ClearableInput label="Descrizione libera" value={description} onChange={setDescription} /><ClearableInput label="Quantità" type="number" min="1" value={quantity} onChange={setQuantity} /><ClearableInput label="Prezzo unitario IVA esclusa" type="number" min="0" step="0.01" value={price} onChange={setPrice} /><ClearableInput label="Aliquota IVA %" type="number" min="0" step="0.01" value={taxRate} onChange={setTaxRate} /><button type="button" className="secondary align-end" onClick={addLine}>＋ Aggiungi riga</button></div>{items.length > 0 && <><div className="document-lines-head"><span>Articolo</span><span>Qtà</span><span>Prezzo netto</span><span>IVA %</span><span>Imponibile</span><span>Totale</span><span /></div><div className="document-lines">{items.map((item) => { const net = item.quantity * item.unitPrice; const gross = net * (1 + item.taxRate / 100); return <div className="document-line-row" key={item.key}><div className="cart-desc"><strong>{item.description}</strong><small>{item.productId ? "Prodotto di magazzino" : "Riga libera"}</small></div><ClearableInput compact aria-label="Quantità documento" type="number" min="0.01" step="0.01" value={item.quantity} onChange={(value) => updateLine(item.key, { quantity: Number(value) || 0 })} /><ClearableInput compact aria-label="Prezzo unitario netto" type="number" min="0" step="0.01" value={item.unitPrice} onChange={(value) => updateLine(item.key, { unitPrice: Number(value) || 0 })} /><ClearableInput compact aria-label="Aliquota IVA" type="number" min="0" step="0.01" value={item.taxRate} onChange={(value) => updateLine(item.key, { taxRate: Number(value) || 0 })} /><b>{money(net)}</b><b>{money(gross)}</b><button className="icon-button" onClick={() => setItems((current) => current.filter((row) => row.key !== item.key))}>×</button></div>; })}</div></>}</div></div><aside className="panel document-summary"><p className="eyebrow">RIEPILOGO</p><h2>{type === "invoice" ? "Fattura" : "Preventivo"}</h2>{type === "invoice" && <div className="document-payment-chip">Pagamento: {paymentMethod === "bank" ? "Bonifico bancario" : paymentMethod === "card" ? "Carta" : "Contanti"}</div>}<div className="total-line"><span>Imponibile</span><b>{money(netTotal)}</b></div><div className="total-line"><span>IVA</span><b>{money(taxTotal)}</b></div><div className="grand-total document-grand-total"><span>Totale</span><strong>{money(netTotal + taxTotal)}</strong></div><button className="primary full-button" disabled={!items.length || !recipient.name} onClick={create}>Genera {type === "invoice" ? "fattura" : "preventivo"} PDF</button>{last && <a className="secondary center full-button" href={`/api/pdf?type=document&id=${last.id}`}>Scarica {last.number}</a>}<div className="recent-documents"><h3>Documenti recenti</h3>{data.documents.slice(0, 12).map((document) => <div className="document-row" key={document.id}><span><strong>{document.number}</strong><small>{document.type === "invoice" ? "Fattura" : "Preventivo"} · {document.recipient}{document.type === "invoice" ? ` · ${document.paymentMethod === "bank" ? "Bonifico" : document.paymentMethod === "card" ? "Carta" : "Contanti"}` : ""}</small></span><b>{money(document.total)}</b><a href={`/api/pdf?type=document&id=${document.id}`}>PDF</a></div>)}</div></aside></div></section>;
}

function Analytics({ data }: { data: Bootstrap }) {
  const [period, setPeriod] = useState<"week" | "month" | "all">("month");
  const [brand, setBrand] = useState("Tutte");
  const [model, setModel] = useState("");
  const brands = useMemo(() => [...new Set(data.products.map((product) => product.brand).filter(Boolean))].sort((left, right) => variantCollator.compare(left, right)), [data.products]);
  const filtered = useMemo(() => {
    const now = new Date();
    const start = period === "month" ? new Date(now.getFullYear(), now.getMonth(), 1) : period === "week" ? new Date(now.getFullYear(), now.getMonth(), now.getDate() - ((now.getDay() + 6) % 7)) : null;
    const query = model.trim().toLocaleLowerCase("it");
    return (data.saleItems ?? []).filter((item) => item.itemType === "product" && (!start || new Date(item.createdAt) >= start) && (brand === "Tutte" || item.brand === brand) && (!query || `${item.productName} ${item.description}`.toLocaleLowerCase("it").includes(query)));
  }, [data.saleItems, period, brand, model]);
  function ranking(store: Store) {
    const map = new Map<string, { name: string; brand: string; quantity: number; total: number }>();
    for (const item of filtered.filter((row) => row.store === store)) {
      const key = item.variantGroup || `${item.brand}|${item.productName}`;
      const row = map.get(key) ?? { name: item.productName || item.description, brand: item.brand, quantity: 0, total: 0 };
      row.quantity += item.quantity; row.total += item.lineTotal; map.set(key, row);
    }
    return [...map.values()].sort((left, right) => right.quantity - left.quantity).slice(0, 15);
  }
  const rankings = { Viterbo: ranking("Viterbo"), "Gran Sasso": ranking("Gran Sasso") };
  return <section className="screen"><div className="screen-head"><div><p className="eyebrow">ANALISI VENDITE</p><h1>Prodotti più venduti per negozio</h1><p className="muted inventory-intro">Confronta subito Viterbo e Gran Sasso, filtrando periodo, marca e modello.</p></div></div><div className="panel analytics-filters"><label className="field"><span>Periodo</span><select value={period} onChange={(event) => setPeriod(event.target.value as "week" | "month" | "all")}><option value="week">Settimana corrente</option><option value="month">Mese corrente</option><option value="all">Tutto lo storico</option></select></label><label className="field"><span>Marca</span><select value={brand} onChange={(event) => setBrand(event.target.value)}><option>Tutte</option>{brands.map((item) => <option key={item}>{item}</option>)}</select></label><ClearableInput label="Modello / prodotto" value={model} onChange={setModel} placeholder="Cerca modello…" /></div><div className="warehouse-grid analytics-stores">{(["Viterbo", "Gran Sasso"] as Store[]).map((store) => { const rows = rankings[store]; const max = Math.max(1, ...rows.map((row) => row.quantity)); return <div className="panel" key={store}><div className="panel-title"><div><p className="eyebrow">CLASSIFICA NEGOZIO</p><h2>{store}</h2></div><span className="count-pill">{rows.reduce((sum, row) => sum + row.quantity, 0)} pezzi</span></div><div className="chart-list">{rows.length ? rows.map((row, index) => <div className="chart-row" key={`${store}-${row.brand}-${row.name}`}><span>{index + 1}</span><div><strong>{row.brand ? `${row.brand} · ` : ""}{row.name}</strong><div className="bar"><i style={{ width: `${Math.max(4, row.quantity / max * 100)}%` }} /></div></div><b>{row.quantity} pz</b><small>{money(row.total)}</small></div>) : <Empty>Nessuna vendita per i filtri selezionati.</Empty>}</div></div>; })}</div></section>;
}

function Dashboard({ data }: { data: Bootstrap }) {
  const today = new Date().toLocaleDateString("it-IT");
  const todaySales = data.sales.filter((sale) => new Date(sale.createdAt).toLocaleDateString("it-IT") === today);
  const totalFor = (sales: Sale[], store: Store) => sales.filter((sale) => sale.store === store).reduce((sum, sale) => sum + sale.total, 0);
  const storeTotals = { Viterbo: totalFor(data.sales, "Viterbo"), "Gran Sasso": totalFor(data.sales, "Gran Sasso") };
  const storeMax = Math.max(1, Math.abs(storeTotals.Viterbo), Math.abs(storeTotals["Gran Sasso"]));
  const trend = Array.from({ length: 7 }, (_, offset) => {
    const date = new Date(); date.setHours(0, 0, 0, 0); date.setDate(date.getDate() - (6 - offset));
    const key = date.toLocaleDateString("it-IT");
    const sales = data.sales.filter((sale) => new Date(sale.createdAt).toLocaleDateString("it-IT") === key);
    return { key, label: date.toLocaleDateString("it-IT", { weekday: "short", day: "2-digit" }), viterbo: totalFor(sales, "Viterbo"), granSasso: totalFor(sales, "Gran Sasso") };
  });
  const trendMax = Math.max(1, ...trend.flatMap((day) => [Math.abs(day.viterbo), Math.abs(day.granSasso)]));
  return <section className="screen"><div className="screen-head"><div><p className="eyebrow">DASHBOARD GENERALE · TEMPO REALE</p><h1>Buongiorno, {data.user.displayName}</h1><p className="muted inventory-intro">Vendite aggregate e confronto immediato tra Viterbo e Gran Sasso.</p></div><div className="live-chip"><i />Firebase Realtime · {today}</div></div><div className="metric-grid"><Metric label="Totale netto di oggi" value={money(todaySales.reduce((sum, sale) => sum + sale.total, 0))} note={`${todaySales.length} movimenti complessivi`} /><Metric label="Viterbo oggi" value={money(totalFor(todaySales, "Viterbo"))} note={`${todaySales.filter((sale) => sale.store === "Viterbo").length} scontrini`} /><Metric label="Gran Sasso oggi" value={money(totalFor(todaySales, "Gran Sasso"))} note={`${todaySales.filter((sale) => sale.store === "Gran Sasso").length} scontrini`} /><Metric label="Prodotti disponibili" value={String(data.products.reduce((sum, product) => sum + product.viterboQty + product.granSassoQty - product.viterboReserved - product.granSassoReserved, 0))} note="nei due negozi" /></div><div className="dashboard-charts"><div className="panel realtime-comparison"><div className="panel-title"><div><p className="eyebrow">CONFRONTO NEGOZI</p><h2>Vendite nette visibili</h2></div><span className="count-pill">{data.sales.length} movimenti</span></div>{(["Viterbo", "Gran Sasso"] as Store[]).map((store) => <div className="store-bar" key={store}><div><strong>{store}</strong><b>{money(storeTotals[store])}</b></div><div className="store-bar-track"><i className={store === "Viterbo" ? "viterbo" : "gran-sasso"} style={{ width: `${Math.max(3, Math.abs(storeTotals[store]) / storeMax * 100)}%` }} /></div></div>)}</div><div className="panel realtime-trend"><div className="panel-title"><div><p className="eyebrow">ULTIMI 7 GIORNI</p><h2>Andamento per punto vendita</h2></div><div className="chart-legend"><span><i className="viterbo" />Viterbo</span><span><i className="gran-sasso" />Gran Sasso</span></div></div><div className="trend-list">{trend.map((day) => <div className="trend-day" key={day.key}><strong>{day.label}</strong><div><span><i className="viterbo" style={{ width: `${Math.abs(day.viterbo) / trendMax * 100}%` }} /></span><small>{money(day.viterbo)}</small></div><div><span><i className="gran-sasso" style={{ width: `${Math.abs(day.granSasso) / trendMax * 100}%` }} /></span><small>{money(day.granSasso)}</small></div></div>)}</div></div></div><div className="warehouse-grid"><div className="panel"><p className="eyebrow">ULTIMI MOVIMENTI</p><h2>Vendite e resi</h2>{data.sales.slice(0, 7).map((sale) => <div className="document-row" key={sale.id}><span><strong>{sale.receiptNo}</strong><small>{sale.store} · {sale.customerName}</small></span><b className={sale.total < 0 ? "negative" : ""}>{money(sale.total)}</b></div>)}</div><div className="panel"><p className="eyebrow">ATTENZIONE</p><h2>Giacenze basse</h2>{data.products.filter((product) => product.viterboQty - product.viterboReserved <= 2 || product.granSassoQty - product.granSassoReserved <= 2).slice(0, 8).map((product) => <div className="document-row" key={product.id}><span><strong>{product.name}</strong><small>{product.color} · {product.size}</small></span><span className="stock-zero">VT {product.viterboQty - product.viterboReserved} · GS {product.granSassoQty - product.granSassoReserved}</span></div>)}</div></div></section>;
}

const fiscalStatusLabel: Record<string, string> = {
  not_configured: "Da configurare",
  token_generated: "Chiave generata",
  disabled: "Disabilitato",
  waiting_bridge: "In attesa del ponte Windows",
  online: "Collegato",
  printing: "Stampa in corso",
  network_ready: "Rete RCH verificata",
  error: "Errore",
};

const fiscalJobLabel: Record<string, string> = {
  awaiting_setup: "Attende configurazione",
  queued: "In coda",
  processing: "In stampa",
  printed: "Stampato",
  error: "Errore",
};

function FiscalRegisters({ data, reload }: { data: Bootstrap; reload: () => Promise<void> }) {
  const [revealed, setRevealed] = useState<{ store: Store; token: string } | null>(null);
  const [message, setMessage] = useState("");
  const [error, setError] = useState("");
  async function generate(store: Store) {
    if (!confirm(`Generare una nuova chiave per ${store}? L'eventuale ponte già configurato smetterà di collegarsi.`)) return;
    setError(""); setMessage("");
    try {
      const result = await post("regenerateFiscalToken", { store });
      setRevealed({ store, token: result.token });
      setMessage(`Chiave ${store} generata. Copiala ora e avvia il pacchetto del negozio: l'installazione la verificherà e abiliterà automaticamente il ponte.`);
      await reload();
    } catch (reason) { setError(reason instanceof Error ? reason.message : "Errore."); }
  }
  async function toggle(device: FiscalDevice) {
    setError(""); setMessage("");
    try {
      await post("setFiscalDeviceEnabled", { store: device.store, enabled: !device.enabled });
      setMessage(`${device.store}: registratore ${device.enabled ? "disabilitato" : "abilitato"}.`);
      await reload();
    } catch (reason) { setError(reason instanceof Error ? reason.message : "Errore."); }
  }
  async function retry(job: FiscalJob) {
    if (!confirm(`Rimettere in coda ${job.receiptNo}? Verifica prima che il registratore non abbia già stampato il documento.`)) return;
    setError(""); setMessage("");
    try { await post("retryFiscalJob", { jobId: job.id }); setMessage(`${job.receiptNo} rimesso in coda.`); await reload(); }
    catch (reason) { setError(reason instanceof Error ? reason.message : "Errore."); }
  }
  return <section className="screen"><div className="screen-head"><div><p className="eyebrow">AMMINISTRAZIONE</p><h1>Registratori telematici</h1><p className="muted inventory-intro">Due collegamenti indipendenti, uno per ogni PC Windows. Le vendite restano nel gestionale anche se il registratore è momentaneamente offline.</p></div></div>{message && <div className="alert success">{message}</div>}{error && <div className="alert danger visual-alert">⚠ {error}</div>}{revealed && <div className="panel fiscal-secret"><div><p className="eyebrow">CHIAVE MOSTRATA UNA SOLA VOLTA · {revealed.store}</p><code>{revealed.token}</code><small>Scarica il pacchetto dello stesso negozio: durante l’installazione la chiave verrà verificata e il ponte sarà abilitato automaticamente.</small></div><button className="secondary" onClick={() => void navigator.clipboard.writeText(revealed.token)}>Copia chiave</button></div>}<div className="fiscal-device-grid">{data.fiscalDevices.map((device) => { const now = new Date(data.generatedAt).getTime(); const lastSeen = device.lastSeenAt ? new Date(device.lastSeenAt).getTime() : 0; const recent = Boolean(device.enabled && lastSeen && now - lastSeen < 15000); const online = Boolean(recent && device.lastStatus === "online"); const networkReady = Boolean(recent && device.lastStatus === "network_ready"); const jobs = data.fiscalJobs.filter((job) => job.store === device.store); return <article className="panel fiscal-device" key={device.id}><div className="panel-title"><div><p className="eyebrow">{device.store.toUpperCase()}</p><h2>{device.vendor} {device.model}</h2></div><span className={`fiscal-state ${online || networkReady ? "ready" : device.lastStatus === "error" ? "failed" : "waiting"}`}><i />{online ? "Collegato" : networkReady ? "Rete RCH verificata" : fiscalStatusLabel[device.lastStatus] ?? device.lastStatus}</span></div><dl className="fiscal-details"><div><dt>Collegamento</dt><dd>{device.connector === "epson_fpmate" ? "EpsonFpMate ufficiale" : "RCH Standard · Wi-Fi 192.168.1.210:23"}</dd></div><div><dt>Ultimo contatto</dt><dd>{device.lastSeenAt ? dateTime(device.lastSeenAt) : "Mai"}</dd></div><div><dt>Chiave ponte</dt><dd>{device.hasToken ? "Generata" : "Da generare"}</dd></div><div><dt>Stato</dt><dd>{device.enabled ? "Abilitato" : "Disabilitato"}</dd></div></dl>{device.lastError && <div className="alert danger compact-alert">{device.lastError}</div>}<div className="form-actions fiscal-actions"><button className="secondary" onClick={() => generate(device.store)}>{device.hasToken ? "Rigenera chiave" : "Genera chiave"}</button><button className={device.enabled ? "danger-button" : "primary"} onClick={() => toggle(device)} disabled={!device.hasToken && !device.enabled}>{device.enabled ? "Disabilita" : "Abilita manualmente"}</button></div>{device.connector === "rch_standard_tcp" && <p className="fine-print">Il ponte invia direttamente gli scontrini tramite Protocollo Standard RCH su 192.168.1.210:23, gestisce la chiusura =c con Opzione Fidelity attiva e conferma la stampa solo dopo l’esito positivo del registratore.</p>}{device.connector === "epson_fpmate" && <p className="fine-print">EpsonFpMate deve essere installato e collaudato sul PC Gran Sasso con reparto e pagamenti corretti.</p>}<div className="fiscal-jobs"><h3>Ultime richieste</h3>{jobs.slice(0, 6).length ? jobs.slice(0, 6).map((job) => { const stale = job.status === "processing" && job.claimedAt && now - new Date(job.claimedAt).getTime() > 120000; return <div className="fiscal-job" key={job.id}><span><strong>{job.receiptNo}</strong><small>{dateTime(job.createdAt)} · tentativi {job.attempts}</small></span><span className={`job-status ${job.status}`}>{fiscalJobLabel[job.status] ?? job.status}</span>{(["error", "awaiting_setup"].includes(job.status) || stale) && <button className="text-button" onClick={() => retry(job)}>Rimetti in coda</button>}</div>; }) : <Empty>Nessuna richiesta fiscale.</Empty>}</div></article>; })}</div><div className="panel fiscal-downloads"><div><p className="eyebrow">INSTALLAZIONE UNICA SUI PC WINDOWS</p><h2>Servizio automatico registratore RT</h2><p className="muted">Il nuovo programma verifica la chiave e abilita automaticamente il negozio durante l’installazione. Se la chiave è errata, si ferma prima di avviare il ponte.</p></div><div className="fiscal-download-actions"><a className="primary" href="/rt-bridge/Marinelli-RT-Viterbo.zip" download>Pacchetto Viterbo · RCH Wi-Fi</a><a className="primary" href="/rt-bridge/Marinelli-RT-Gran-Sasso.zip" download>Pacchetto Gran Sasso · Epson</a><a className="text-button" href="/rt-bridge/INSTALLAZIONE.txt" target="_blank" rel="noreferrer">Istruzioni per il tecnico</a></div></div><div className="panel fiscal-install-note"><strong>Installazione iniziale obbligatoria</strong><p>Per sicurezza i registratori non vengono esposti su Internet. Il tecnico installa una sola volta il collegamento locale e configura reparti IVA, pagamenti e driver ufficiali; in seguito non occorre aprire alcun programma.</p></div></section>;
}

function Settings({ reload }: { reload: () => Promise<void> }) {
  const [confirmation, setConfirmation] = useState(""); const [message, setMessage] = useState(""); const [error, setError] = useState("");
  async function reset() { if (!confirm("Confermi l'eliminazione totale di prodotti, EAN, giacenze, vendite, clienti, buoni, acconti e documenti?")) return; setError(""); try { await post("resetData", { confirmation }); setConfirmation(""); setMessage("Tutti i dati operativi sono stati eliminati. Sono rimasti gli account Firebase e le configurazioni dei registratori RT."); await reload(); } catch (reason) { setError(reason instanceof Error ? reason.message : "Errore."); } }
  return <section className="screen"><div className="screen-head"><div><p className="eyebrow">AMMINISTRAZIONE</p><h1>Impostazioni</h1></div></div>{message && <div className="alert success">{message}</div>}{error && <div className="alert danger">{error}</div>}<div className="two-columns"><div className="panel"><p className="eyebrow">SICUREZZA FIREBASE</p><h2>Accessi e password</h2><p className="muted">Gli accessi autorizzati sono <strong>admin</strong>, <strong>viterbo</strong> e <strong>gran-sasso</strong>. Le password sono gestite esclusivamente da Firebase Authentication e non vengono salvate nel codice o nel database del gestionale.</p><div className="firebase-account-list"><span><b>admin</b><small>Dashboard globale · entrambi i negozi</small></span><span><b>viterbo</b><small>Cassa e dati del negozio Viterbo</small></span><span><b>gran-sasso</b><small>Cassa e dati del negozio Gran Sasso</small></span></div></div><div className="panel danger-zone"><p className="eyebrow">OPERAZIONE IRREVERSIBILE</p><h2>Elimina tutto</h2><p className="muted">Elimina definitivamente prodotti, varianti EAN, giacenze, vendite, resi, clienti, buoni, prenotazioni, trasferimenti, richieste fiscali e documenti. Conserva gli account Firebase e le configurazioni hardware dei registratori RT.</p><ClearableInput label={'Scrivi “AZZERA TUTTO”'} value={confirmation} onChange={setConfirmation} /><button className="danger-button" disabled={confirmation !== "AZZERA TUTTO"} onClick={reset}>Elimina tutti i dati</button></div></div></section>;
}

const adminMenu = [["dashboard", "▦", "Riepilogo"], ["manage", "✎", "Modifica e cancella"], ["cash", "▣", "Cassa"], ["customers", "◎", "Clienti"], ["inventory", "◫", "Magazzini"], ["reorder", "!", "Articoli da riordinare"], ["transfers", "⇄", "Trasferimenti"], ["load", "＋", "Carico prodotti"], ["documents", "▤", "Fatturazione"], ["register", "≡", "Registro casse"], ["reports", "▥", "Corrispettivi"], ["gifts", "◇", "Riepilogo buoni regalo"], ["reservations", "▣", "Prenotazioni e acconti"], ["analytics", "↗", "Analisi vendite"], ["fiscal", "RT", "Registratori RT"], ["settings", "⚙", "Impostazioni"]] as const;
const cashierMenu = [["cash", "▣", "Cassa"], ["customers", "◎", "Clienti"], ["inventory", "◫", "Ricerca prodotti"], ["load", "＋", "Carico prodotti"], ["register", "≡", "Vendite effettuate"], ["transfers", "⇄", "Trasferimenti"], ["reservations", "▣", "Acconti e ritiri"]] as const;

export default function Gestionale() {
  const [user, setUser] = useState<User | null>(null); const [data, setData] = useState<Bootstrap | null>(null); const [loading, setLoading] = useState(true); const [page, setPage] = useState("dashboard"); const [menuOpen, setMenuOpen] = useState(false); const [fatal, setFatal] = useState(""); const [syncState, setSyncState] = useState<"online" | "syncing" | "offline">("syncing");
  const refreshInFlight = useRef(false);
  const reload = useCallback(async (background = false) => {
    if (refreshInFlight.current) return;
    refreshInFlight.current = true;
    if (!background) setSyncState("syncing");
    try {
      const result = await readJson(await firebaseAuthenticatedFetch("/api/data?view=bootstrap", { cache: "no-store" }));
      setData(result as Bootstrap);
      setUser((result as Bootstrap).user);
      setFatal("");
      setSyncState("online");
    } catch (reason) {
      if ((reason as { status?: number }).status === 401) {
        setUser(null);
        setData(null);
      } else {
        setSyncState("offline");
        if (!background) setFatal(reason instanceof Error ? reason.message : "Errore di caricamento.");
      }
    } finally {
      refreshInFlight.current = false;
    }
  }, []);
  useEffect(() => onIdTokenChanged(firebaseAuth, async (firebaseUser) => {
    if (!firebaseUser) {
      await fetch("/api/auth", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ action: "logout" }) }).catch(() => undefined);
      setUser(null); setData(null); setLoading(false); return;
    }
    try {
      const result = await readJson(await establishServerSession(firebaseUser));
      const nextUser = result.user as User;
      setUser(nextUser);
      setPage(nextUser.role === "admin" ? "dashboard" : "cash");
      await reload();
    } catch {
      await signOut(firebaseAuth).catch(() => undefined);
      setUser(null); setData(null);
    } finally { setLoading(false); }
  }), [reload]);
  useEffect(() => {
    if (!user?.id) return;
    const paths = user.role === "admin" ? ["stores/viterbo/sales", "stores/gran-sasso/sales"] : [`stores/${firebaseStoreNode(user.store ?? "Viterbo")}/sales`];
    let initialized = 0;
    const unsubscribes = paths.map((path) => onValue(ref(firebaseDatabase, path), () => {
      if (initialized < paths.length) { initialized += 1; if (initialized === paths.length) setSyncState("online"); return; }
      setSyncState("syncing");
      void reload(true);
    }, () => setSyncState("offline")));
    return () => unsubscribes.forEach((unsubscribe) => unsubscribe());
  }, [user?.id, user?.role, user?.store, reload]);
  useEffect(() => {
    if (!user?.id) return;
    const refreshWhenActive = () => { if (document.visibilityState === "visible") void reload(true); };
    const interval = window.setInterval(refreshWhenActive, 30000);
    window.addEventListener("focus", refreshWhenActive);
    document.addEventListener("visibilitychange", refreshWhenActive);
    return () => {
      window.clearInterval(interval);
      window.removeEventListener("focus", refreshWhenActive);
      document.removeEventListener("visibilitychange", refreshWhenActive);
    };
  }, [user?.id, reload]);
  async function logout() { await Promise.allSettled([signOut(firebaseAuth), fetch("/api/auth", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ action: "logout" }) })]); setUser(null); setData(null); setSyncState("syncing"); }
  if (loading) return <main className="loading-page"><div className="brand-mark">MS</div><p>Avvio del Gestionale…</p></main>;
  if (!user) return <Login onLogin={(nextUser) => { setUser(nextUser); setPage(nextUser.role === "admin" ? "dashboard" : "cash"); void reload(); }} />;
  if (!data) return <main className="loading-page"><p>{fatal || "Caricamento dati…"}</p><button className="primary" onClick={() => void reload()}>Riprova</button></main>;
  const menu = user.role === "admin" ? adminMenu : cashierMenu;
  const content: Record<string, ReactNode> = { dashboard: <Dashboard data={data} />, manage: <AdminDataManagement data={data} reload={reload} />, cash: <NewCashRegister data={data} reload={reload} />, customers: <Customers data={data} reload={reload} />, inventory: <Inventory data={data} />, reorder: <ReorderList data={data} />, transfers: <Transfers data={data} reload={reload} />, load: <QuickLoad data={data} reload={reload} />, documents: <Documents data={data} reload={reload} />, register: <Register data={data} />, reports: <CashReports data={data} />, gifts: <GiftSummary data={data} />, reservations: <ReservationSummary data={data} />, analytics: <Analytics data={data} />, fiscal: <FiscalRegisters data={data} reload={reload} />, settings: <Settings reload={reload} /> };
  const syncTime = new Date(data.generatedAt).toLocaleTimeString("it-IT", { hour: "2-digit", minute: "2-digit", second: "2-digit" });
  const syncLabel = syncState === "offline" ? "Connessione assente" : syncState === "syncing" ? "Sincronizzazione…" : "Dati in tempo reale";
  return <div className="app-shell"><button className="mobile-menu" onClick={() => setMenuOpen((value) => !value)}>☰ Menu</button><aside className={`sidebar ${menuOpen ? "open" : ""}`}><div className="sidebar-brand"><div className="brand-mark small-mark">MS</div><div><strong>Gestionale</strong><small>Marinelli Stefano</small></div></div><nav>{menu.map(([id, icon, label]) => <button key={id} className={page === id ? "active" : ""} onClick={() => { setPage(id); setMenuOpen(false); }}><span>{icon}</span>{label}</button>)}</nav><button type="button" className={`sidebar-sync ${syncState}`} onClick={() => void reload()} title="Aggiorna ora"><i /><span><strong>{syncLabel}</strong><small>{syncState === "offline" ? "Clicca per riprovare" : `Aggiornato alle ${syncTime}`}</small></span></button><div className="sidebar-user"><div className="avatar">{user.displayName.slice(0, 2).toUpperCase()}</div><span><strong>{user.displayName}</strong><small>{user.store ?? "Amministrazione"}</small></span><button className="icon-button" onClick={logout} title="Esci">↪</button></div></aside><main className="app-main">{content[page] ?? content.cash}</main></div>;
}
